'use strict';
// 100 algorithm families, each with ten explicit teaching scenarios. The
// parameters are part of the problem and the solution, not renamed copies.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const B=(type,fields={},inputs={},extraState)=>({type,...(Object.keys(fields).length?{fields}:{}),...(Object.keys(inputs).length?{inputs:Object.fromEntries(Object.entries(inputs).map(([key,block])=>[key,{block}]))}:{}),...(extraState?{extraState}:{})});
const N=NUM=>B('math_number',{NUM}),T=TEXT=>B('text',{TEXT}),V=name=>B('variables_get',{VAR:{id:'v-'+name}}),S=(name,VALUE)=>B('variables_set',{VAR:{id:'v-'+name}},{VALUE});
const A=(OP,a,b)=>B('math_arithmetic',{OP},{A:a,B:b}),add=(a,b)=>A('ADD',a,b),sub=(a,b)=>A('MINUS',a,b),mul=(a,b)=>A('MULTIPLY',a,b),div=(a,b)=>A('DIVIDE',a,b),pow=(a,b)=>A('POWER',a,b),mod=(DIVIDEND,DIVISOR)=>B('math_modulo',{},{DIVIDEND,DIVISOR});
const C=(OP,a,b)=>B('logic_compare',{OP},{A:a,B:b}),and=(a,b)=>B('logic_operation',{OP:'AND'},{A:a,B:b}),or=(a,b)=>B('logic_operation',{OP:'OR'},{A:a,B:b});
const round=(OP,NUM)=>B('math_round',{OP},{NUM}),floor=a=>round('ROUNDDOWN',a),ceil=a=>round('ROUNDUP',a),abs=a=>B('math_single',{OP:'ABS'},{NUM:a}),sqrt=a=>B('math_single',{OP:'ROOT'},{NUM:a});
const join=(...parts)=>B('text_join',{},Object.fromEntries(parts.map((v,i)=>['ADD'+i,v])),{itemCount:parts.length});
const len=VALUE=>B('text_length',{},{VALUE}),char=(VALUE,AT)=>B('text_charAt',{WHERE:'FROM_START'},{VALUE,AT}),index=(VALUE,FIND)=>B('text_indexOf',{END:'FIRST'},{VALUE,FIND});
const L=(...parts)=>B('lists_create_with',{},Object.fromEntries(parts.map((v,i)=>['ADD'+i,v])),{itemCount:parts.length});
const llen=VALUE=>B('lists_length',{},{VALUE}),at=(VALUE,AT)=>B('lists_getIndex',{MODE:'GET',WHERE:'FROM_START'},{VALUE,AT});
const put=(LIST,AT,TO)=>B('lists_setIndex',{MODE:'SET',WHERE:'FROM_START'},{LIST,AT,TO}),append=(LIST,TO)=>B('lists_setIndex',{MODE:'INSERT',WHERE:'LAST'},{LIST,TO});
const P=TEXT=>B('edu_print',{},{TEXT}),read=label=>B('edu_number_input',{},{PROMPT:T(label)}),readText=label=>B('edu_input',{},{PROMPT:T(label)});
const seq=(...blocks)=>{const parts=blocks.flat().filter(Boolean).map(block=>structuredClone(block));for(let i=0;i<parts.length-1;i++){let tail=parts[i];while(tail.next?.block)tail=tail.next.block;tail.next={block:parts[i+1]};}return parts[0];};
const IF=(IF0,DO0,ELSE)=>B('controls_if',{},{IF0,DO0,...(ELSE?{ELSE}:{})},ELSE?{hasElse:true}:undefined);
const FOR=(name,FROM,TO,BY,...body)=>B('controls_for',{VAR:{id:'v-'+name}},{FROM,TO,BY,DO:seq(...body)});
const REPEAT=(TIMES,...body)=>B('controls_repeat_ext',{},{TIMES,DO:seq(...body)}),WHILE=(BOOL,...body)=>B('controls_whileUntil',{MODE:'WHILE'},{BOOL,DO:seq(...body)});
const INC=(name,delta)=>S(name,add(V(name),delta));
const move=N=>B('edu_move',{},{N}),turn=N=>B('edu_turn',{},{N}),pen=state=>B('edu_pen',{STATE:state?'1':'0'}),go=(X,Y)=>B('edu_goto',{},{X,Y});
const R2=x=>div(round('ROUND',mul(x,N(100))),N(100)),R4=x=>div(round('ROUND',mul(x,N(10000))),N(10000));
const readFixed=(count,name='brojevi')=>seq(S(name,L()),FOR('i',N(1),N(count),N(1),append(V(name),read('Broj'))));
const readDynamic=(name='brojevi')=>seq(S('n',read('Broj elemenata')),S(name,L()),FOR('i',N(1),V('n'),N(1),append(V(name),read('Broj'))));
const gcdBlocks=()=>WHILE(C('NEQ',V('b'),N(0)),S('ostatak',mod(V('a'),V('b'))),S('a',V('b')),S('b',V('ostatak')));
const out=values=>(Array.isArray(values)?values:[values]).map(String).join('\n');
const nums=input=>input.split('\n').map(Number),line=(...values)=>values.flat().join('\n');
const gcd=(a,b)=>{a=Math.abs(a);b=Math.abs(b);while(b){const t=b;b=a%b;a=t;}return a;};
const r2=x=>Math.round(x*100)/100,r4=x=>Math.round(x*10000)/10000;
const isPrime=n=>n>=2&&!Array.from({length:Math.max(0,Math.floor(Math.sqrt(n))-1)},(_,i)=>i+2).some(d=>n%d===0);
const sortBlocks=(name='brojevi',count=llen(V(name)))=>REPEAT(sub(count,N(1)),FOR('j',N(1),sub(count,N(1)),N(1),IF(C('GT',at(V(name),V('j')),at(V(name),add(V('j'),N(1)))),seq(S('privremeni',at(V(name),V('j'))),put(V(name),V('j'),at(V(name),add(V('j'),N(1)))),put(V(name),add(V('j'),N(1)),V('privremeni'))))));
function project(roots){const blocks=Array.isArray(roots)?roots:[roots],names=new Set();const visit=value=>{if(!value||typeof value!=='object')return;if(value.fields?.VAR?.id)names.add(value.fields.VAR.id);Object.values(value).forEach(visit);};visit(blocks);return {format:'ELDI-BLOCKS-1',workspace:{blocks:{languageVersion:0,blocks:blocks.map((block,i)=>({...block,x:30+i*360,y:30}))},...(names.size?{variables:[...names].map(id=>({id,name:id.slice(2)}))}:{})}};}
const families=[];
function F(id,grade,category,title,make){families.push({id,grade,category,title,make});}
function task(setting,statement,roots,samples,calculate,steps,extra={}){return {setting,statement,roots,samples,calculate,steps:steps||['Učitaj tražene podatke u varijable.','Primijeni navedeno pravilo pomoću odgovarajućih blokova.','Ispiši rezultat i provjeri drugi primjer ulaza.'],...extra};}

// 5. razred: useful everyday computations and introductory block programs.
F('kupovina',5,'Računanje','Račun za dvije vrste proizvoda',k=>task(`cijene ${k+1} i ${k+3} KM`,`Učitaj količine dva proizvoda iz dva reda. Cijene po komadu su ${k+1} KM i ${k+3} KM. Ispiši ukupnu cijenu bez dodatnog teksta.`,seq(S('a',read('Prva količina')),S('b',read('Druga količina')),P(add(mul(V('a'),N(k+1)),mul(V('b'),N(k+3))))),[line(k+2,3),line(0,5),line(7,0)],s=>{const[a,b]=nums(s);return a*(k+1)+b*(k+3);},['Učitaj obje količine.','Svaku pomnoži njenom cijenom; cijene su dio ovog scenarija.','Saberi troškove i ispiši zbir.']));
F('kusur',5,'Računanje','Kusur nakon kupovine',k=>task(`cijena ${k+2} KM`,`Učitaj predani iznos i broj kupljenih artikala iz dva reda. Jedan artikal košta ${k+2} KM. Ispiši kusur: iznos − broj artikala × cijena.`,seq(S('iznos',read('Predani iznos')),S('komada',read('Broj artikala')),P(sub(V('iznos'),mul(V('komada'),N(k+2))))),[line(100,k+1),line(50,0),line((k+2)*4,4)],s=>{const[a,b]=nums(s);return a-b*(k+2);}));
F('pakovanje',5,'Računanje','Pune kutije i ostatak',k=>task(`kutija za ${k+3} predmeta`,`Učitaj broj predmeta (nenegativan cijeli broj). U kutiju stane ${k+3} predmeta. Ispiši broj punih kutija, pa broj preostalih predmeta u drugom redu.`,seq(S('n',read('Broj predmeta')),P(floor(div(V('n'),N(k+3)))),P(mod(V('n'),N(k+3)))),[line((k+3)*4+2),line(0),line(k+3)],s=>[Math.floor(Number(s)/(k+3)),Number(s)%(k+3)]));
F('trajanje',5,'Računanje','Trajanje aktivnosti u sekundama',k=>task(`pauza ${k*15} sekundi`,`Učitaj trajanje rada u minutama. Dodaj pauzu od ${k*15} sekundi i ispiši ukupno trajanje u sekundama.`,seq(S('minute',read('Minute rada')),P(add(mul(V('minute'),N(60)),N(k*15)))),[line(k+2),line(0),line(25)],s=>Number(s)*60+k*15));
F('put',5,'Računanje','Pređeni put',k=>task(`brzina ${k+2} km/h`,`Učitaj vrijeme kretanja u satima. Brzina je ${k+2} km/h, a prije mjerenja već je pređeno ${k} km. Ispiši ukupan put u kilometrima.`,seq(S('sati',read('Vrijeme u satima')),P(add(mul(V('sati'),N(k+2)),N(k)))),[line(3),line(0),line(5)],s=>Number(s)*(k+2)+k));
F('obim-poligona',5,'Geometrija','Obim pravilnog mnogougla',k=>task(`${k+2} stranica`,`Učitaj dužinu stranice pravilnog mnogougla sa ${k+2} stranica. Ispiši obim koristeći množenje.`,seq(S('a',read('Dužina stranice')),P(mul(N(k+2),V('a')))),[line(k+3),line(1),line(20)],s=>(k+2)*Number(s)));
F('povrsina-pravougaonika',5,'Geometrija','Površina pravougaone ploče',k=>task(`širina ${k+4} cm`,`Učitaj dužinu pravougaone ploče. Širina je ${k+4} cm. Ispiši površinu u cm².`,seq(S('duzina',read('Dužina u cm')),P(mul(V('duzina'),N(k+4)))),[line(10),line(2),line(25)],s=>Number(s)*(k+4)));
F('povrsina-trougla',5,'Geometrija','Površina trougla iz visine',k=>task(`osnovica ${2*(k+2)} cm`,`Učitaj visinu trougla. Osnovica je ${2*(k+2)} cm. Ispiši površinu osnovica × visina / 2.`,seq(S('h',read('Visina')),P(div(mul(N(2*(k+2)),V('h')),N(2)))),[line(7),line(2),line(15)],s=>(k+2)*Number(s)));
F('pretvaranje-jedinica',5,'Računanje','Mjerenje u manjim jedinicama',k=>task(`faktor ${[10,100,1000,60,24,7,12,10000,100000,1000000][k-1]}`,`U ovom modelu jedna velika jedinica sadrži ${[10,100,1000,60,24,7,12,10000,100000,1000000][k-1]} malih jedinica. Učitaj broj velikih jedinica i ispiši broj malih.`,seq(S('mjera',read('Velike jedinice')),P(mul(V('mjera'),N([10,100,1000,60,24,7,12,10000,100000,1000000][k-1])))),[line(3),line(0),line(7)],s=>Number(s)*[10,100,1000,60,24,7,12,10000,100000,1000000][k-1]));
F('razmjena-bodova',5,'Računanje','Pretvaranje bodova u žetone',k=>task(`${k+1} bodova po žetonu`,`Učitaj broj bodova. Za jedan žeton treba ${k+1} bodova. Ispiši najveći cijeli broj žetona koji se može dobiti.`,seq(S('bodovi',read('Bodovi')),P(floor(div(V('bodovi'),N(k+1))))),[line(57),line(0),line((k+1)*8)],s=>Math.floor(Number(s)/(k+1))));
F('pozdrav',5,'Tekst','Poruka s unesenim imenom',k=>{const labels=['biblioteku','matematičku sekciju','informatičku sekciju','radionicu robota','šahovsku sekciju','eko tim','školski kviz','klub čitalaca','naučni klub','programerski klub'];const place=labels[k-1];return task(place,`Učitaj ime iz jednog reda. Ispiši tačno: „Dobro došli u ${place}, IME!“; IME zamijeni stvarnim unosom.`,seq(S('ime',readText('Ime')),P(join(T(`Dobro došli u ${place}, `),V('ime'),T('!')))),['Amina','Elvir Čajić','Dino'],s=>`Dobro došli u ${place}, ${s}!`);});
F('duzina-oznake',5,'Tekst','Dužina sastavljene oznake',k=>{const prefix='EDU'+String(k).padStart(2,'0')+'-';return task(`prefiks ${prefix}`,`Učitaj oznaku učenika. Puni kod nastaje dodavanjem prefiksa „${prefix}“ ispred unosa. Ispiši puni kod, zatim njegov broj znakova u drugom redu.`,seq(S('oznaka',readText('Oznaka')),S('puni',join(T(prefix),V('oznaka'))),P(V('puni')),P(len(V('puni')))),['ABC','A1','MATEMATIKA'],s=>[prefix+s,(prefix+s).length]);});
F('ponavljanje-poruke',5,'Petlje','Ponavljanje obavijesti',k=>{const messages=['Ponesi svesku','Provjeri ulaz','Sačuvaj projekat','Pročitaj zadatak','Nacrtaj skicu','Uporedi rezultate','Objasni postupak','Testiraj primjer','Dodaj komentar','Podijeli znanje'];const message=messages[k-1];return task(message,`Učitaj broj ponavljanja od 1 do 10. Ispiši poruku „${message}“ toliko puta, svaki put u novom redu.`,seq(S('n',read('Broj ponavljanja')),REPEAT(V('n'),P(T(message)))),[line(3),line(1),line(5)],s=>Array(Number(s)).fill(message));});
F('korak-niza',5,'Petlje','Brojevi s jednakim korakom',k=>task(`korak ${k+1}`,`Učitaj broj članova od 1 do 15. Ispiši niz počevši od ${k}, pri čemu svaki sljedeći član raste za ${k+1}.`,seq(S('n',read('Broj članova')),S('vrijednost',N(k)),REPEAT(V('n'),P(V('vrijednost')),INC('vrijednost',N(k+1)))),[line(4),line(1),line(7)],s=>Array.from({length:Number(s)},(_,i)=>k+i*(k+1))));
F('odbrojavanje',5,'Petlje','Odbrojavanje intervala',k=>task(`interval ${k+1} sekundi`,`Učitaj broj intervala od 1 do 12. Ispiši preostala vremena od broj_intervala × ${k+1} sekundi do ${k+1}, pa riječ „Kreni!“.`,seq(S('n',read('Broj intervala')),S('vrijeme',mul(V('n'),N(k+1))),REPEAT(V('n'),P(V('vrijeme')),INC('vrijeme',N(-(k+1)))),P(T('Kreni!'))),[line(4),line(1),line(6)],s=>[...Array.from({length:Number(s)},(_,i)=>(Number(s)-i)*(k+1)),'Kreni!']));
F('tablica-mnozenja',5,'Petlje','Tablica množenja',k=>task(`množilac ${k+2}`,`Učitaj broj redova od 1 do 12. Ispiši proizvode ${k+2} × i za i od 1 do broja redova, svaki rezultat zasebno.`,seq(S('n',read('Broj redova')),FOR('i',N(1),V('n'),N(1),P(mul(N(k+2),V('i'))))),[line(4),line(1),line(10)],s=>Array.from({length:Number(s)},(_,i)=>(i+1)*(k+2))));
F('zbir-serije',5,'Petlje','Zbir bodova kroz runde',k=>task(`vrijednost boda ${k+1}`,`Učitaj broj rundi od 1 do 15. U rundi i dobija se i × ${k+1} bodova. Petljom izračunaj ukupan zbir bodova.`,seq(S('n',read('Broj rundi')),S('zbir',N(0)),FOR('i',N(1),V('n'),N(1),INC('zbir',mul(V('i'),N(k+1)))),P(V('zbir'))),[line(4),line(1),line(8)],s=>Number(s)*(Number(s)+1)/2*(k+1)));
F('ponderisani-prosjek',5,'Računanje','Ponderisani rezultat dva rada',k=>task(`težine ${k} i 1`,`Učitaj bodove prvog i drugog rada iz dva reda. Prvi rad ima težinu ${k}, drugi težinu 1. Ispiši prosjek (${k}a + b)/${k+1}, zaokružen na dvije decimale.`,seq(S('a',read('Prvi rad')),S('b',read('Drugi rad')),P(R2(div(add(mul(N(k),V('a')),V('b')),N(k+1))))),[line(80,60),line(0,100),line(75,75)],s=>{const[a,b]=nums(s);return r2((k*a+b)/(k+1));}));
F('crtanje-poligona',5,'Pozornica','Mnogougao promjenjive stranice',k=>task(`${k+2} stranica`,`Učitaj dužinu stranice od 5 do 25 koraka. Nacrtaj pravilni ${k+2}-ugao petljom: idi za stranicu i okreni se za 360/${k+2} stepeni. Ispiši obim.`,seq(S('a',read('Stranica')),REPEAT(N(k+2),move(V('a')),turn(div(N(360),N(k+2)))),P(mul(N(k+2),V('a')))),[line(10),line(15),line(20)],s=>Number(s)*(k+2),['Učitaj stranicu; ne zamjenjuj ulaz unaprijed izračunatom vrijednošću.','Ponovi kretanje i spoljašnji ugao onoliko puta koliko ima stranica.','Provjeri povratak u početak i ispis obima.'],{stage:s=>({type:'stage',x:0,y:0,heading:360,trailCount:k+2,closed:true,segmentLengths:Array(k+2).fill(Number(s)),segmentAngles:Array.from({length:k+2},(_,i)=>-i*360/(k+2)),tolerance:.001})}));
F('stepenice',5,'Pozornica','Stubište iz ponavljanja',k=>task(`širina ${k+5}, visina ${k+2}`,`Učitaj broj stepenica od 1 do 6. Svaka ima vodoravni dio ${k+5} i uspravni dio ${k+2} koraka. Crtaj desno i gore, pa ispiši broj nacrtanih duži.`,seq(S('n',read('Broj stepenica')),REPEAT(V('n'),move(N(k+5)),turn(N(-90)),move(N(k+2)),turn(N(90))),P(mul(V('n'),N(2)))),[line(3),line(1),line(5)],s=>Number(s)*2,undefined,{stage:s=>({type:'stage',x:Number(s)*(k+5),y:Number(s)*(k+2),heading:0,trailCount:Number(s)*2,width:Number(s)*(k+5),height:Number(s)*(k+2)})}));

// 6. razred: decisions, exact fractions and data accumulation.
F('djeljivost',6,'Djeljivost','Provjera djeljivosti',k=>{const d=[2,4,5,6,9,10,15,25,3,8][k-1];return task(`djelilac ${d}`,`Učitaj cijeli broj. Ispiši „DA“ ako je djeljiv sa ${d}, inače „NE“.`,seq(S('n',read('Cijeli broj')),IF(C('EQ',mod(V('n'),N(d)),N(0)),P(T('DA')),P(T('NE')))),[line(d*7),line(d*3+1),line(0)],s=>Number(s)%d===0?'DA':'NE');});
F('dvostruka-djeljivost',6,'Djeljivost','Zajednička djeljivost',k=>{const a=k+2,b=k+3;return task(`djelioci ${a} i ${b}`,`Učitaj cijeli broj. Ispiši „DA“ samo ako je djeljiv i sa ${a} i sa ${b}, inače „NE“.`,seq(S('n',read('Cijeli broj')),IF(and(C('EQ',mod(V('n'),N(a)),N(0)),C('EQ',mod(V('n'),N(b)),N(0))),P(T('DA')),P(T('NE')))),[line(a*b*2),line(a),line(a*b+1)],s=>Number(s)%a===0&&Number(s)%b===0?'DA':'NE');});
F('zaokruzivanje-pakovanja',6,'Grananje','Potrebne kutije',k=>task(`kapacitet ${k+4}`,`Učitaj broj predmeta (nenegativan). Kutija prima ${k+4} predmeta. Ispiši broj kutija potreban za sve predmete, uključujući djelimično punu kutiju.`,seq(S('n',read('Broj predmeta')),P(ceil(div(V('n'),N(k+4))))),[line((k+4)*3+1),line(0),line(k+4)],s=>Math.ceil(Number(s)/(k+4))));
F('temperaturni-prag',6,'Grananje','Upozorenje senzora',k=>task(`prag ${k+15} °C`,`Učitaj temperaturu. Ispiši „visoka“ ako je temperatura strogo veća od ${k+15} °C, inače „normalna“.`,seq(S('t',read('Temperatura')),IF(C('GT',V('t'),N(k+15)),P(T('visoka')),P(T('normalna')))),[line(k+16),line(k+15),line(-2)],s=>Number(s)>k+15?'visoka':'normalna'));
F('dozvoljeni-raspon',6,'Grananje','Podatak u dozvoljenom rasponu',k=>task(`raspon ${k}–${k+20}`,`Učitaj broj. Ispiši „unutar“ ako pripada zatvorenom intervalu [${k}, ${k+20}], uključujući granice; inače „izvan“.`,seq(S('n',read('Broj')),IF(and(C('GTE',V('n'),N(k)),C('LTE',V('n'),N(k+20))),P(T('unutar')),P(T('izvan')))),[line(k),line(k+20),line(k-1)],s=>Number(s)>=k&&Number(s)<=k+20?'unutar':'izvan'));
F('minimum-mjerenja',6,'Grananje','Najmanje korigovano mjerenje',k=>task(`korekcija −${k}`,`Učitaj tri mjerenja. Svako mjerenje koriguje se oduzimanjem ${k}. Pronađi najmanje mjerenje grananjem i ispiši korigovani minimum.`,seq(S('a',read('Prvo')),S('b',read('Drugo')),S('c',read('Treće')),S('najmanji',V('a')),IF(C('LT',V('b'),V('najmanji')),S('najmanji',V('b'))),IF(C('LT',V('c'),V('najmanji')),S('najmanji',V('c'))),P(sub(V('najmanji'),N(k)))),[line(12,7,18),line(5,5,5),line(-2,0,8)],s=>Math.min(...nums(s))-k));
F('maksimum-mjerenja',6,'Grananje','Najveće korigovano mjerenje',k=>task(`korekcija +${k}`,`Učitaj tri mjerenja. Nakon korekcije +${k} na svako mjerenje, ispiši najveće. Minimum ili maksimum ne upisuj unaprijed.`,seq(S('a',read('Prvo')),S('b',read('Drugo')),S('c',read('Treće')),S('najveci',V('a')),IF(C('GT',V('b'),V('najveci')),S('najveci',V('b'))),IF(C('GT',V('c'),V('najveci')),S('najveci',V('c'))),P(add(V('najveci'),N(k)))),[line(12,7,18),line(5,5,5),line(-2,0,8)],s=>Math.max(...nums(s))+k));
F('odstupanje',6,'Računanje','Odstupanje od cilja',k=>task(`cilj ${10*k}`,`Učitaj mjerenje i ispiši apsolutno odstupanje od ciljne vrijednosti ${10*k}. Rezultat treba biti nenegativan.`,seq(S('x',read('Mjerenje')),P(abs(sub(V('x'),N(10*k))))),[line(10*k+3),line(10*k-5),line(10*k)],s=>Math.abs(Number(s)-10*k)));
F('dodatak-procenat',6,'Procenti','Cijena sa dodatkom',k=>task(`dodatak ${k*2}%`,`Učitaj osnovnu cijenu. Dodaj ${k*2}% i ispiši konačnu cijenu zaokruženu na dvije decimale.`,seq(S('cijena',read('Osnovna cijena')),P(R2(mul(V('cijena'),div(N(100+2*k),N(100)))))),[line(80),line(19),line(0)],s=>r2(Number(s)*(100+2*k)/100)));
F('popust',6,'Procenti','Cijena poslije popusta',k=>task(`popust ${k*5}%`,`Učitaj početnu cijenu. Primijeni popust ${k*5}% i ispiši novu cijenu zaokruženu na dvije decimale.`,seq(S('cijena',read('Početna cijena')),P(R2(mul(V('cijena'),div(N(100-5*k),N(100)))))),[line(120),line(37),line(0)],s=>r2(Number(s)*(100-5*k)/100)));
F('tarifa',6,'Grananje','Potrošnja sa uključenim jedinicama',k=>task(`${k+2} uključenih jedinica`,`Učitaj potrošnju. Pretplata je ${k+5} KM i uključuje ${k+2} jedinica. Svaka dodatna jedinica košta 2 KM. Ispiši račun, koristeći grananje kad potrošnja ne prelazi uključeni iznos.`,seq(S('potrosnja',read('Potrošnja')),S('racun',N(k+5)),IF(C('GT',V('potrosnja'),N(k+2)),INC('racun',mul(sub(V('potrosnja'),N(k+2)),N(2)))),P(V('racun'))),[line(k+7),line(k+2),line(0)],s=>k+5+Math.max(0,Number(s)-(k+2))*2));
for(const [id,title,op] of [['razlomak-zbir','Sabiranje razlomaka','ADD'],['razlomak-razlika','Oduzimanje razlomaka','MINUS'],['razlomak-proizvod','Množenje razlomaka','MULTIPLY'],['razlomak-kolicnik','Dijeljenje razlomaka','DIVIDE']])F(id,6,'Razlomci',title,k=>{const p=k,q=k+2;const expr=op==='ADD'?add(mul(N(p),V('d')),mul(V('c'),N(q))):op==='MINUS'?sub(mul(N(p),V('d')),mul(V('c'),N(q))):op==='MULTIPLY'?mul(N(p),V('c')):mul(N(p),V('d'));const denom=op==='DIVIDE'?mul(N(q),V('c')):mul(N(q),V('d'));return task(`prvi razlomak ${p}/${q}`,`Prvi razlomak je ${p}/${q}. Učitaj brojilac c i pozitivan imenilac d drugog razlomka iz dva reda${op==='DIVIDE'?'; c mora biti pozitivan':''}. ${title}: ispiši novi brojilac, zatim novi imenilac u drugom redu. Ovaj početni zadatak ne skraćuje rezultat.`,seq(S('c',read('Brojilac')),S('d',read('Imenilac')),P(expr),P(denom)),[line(2,3),line(1,5),line(3,4)],s=>{const[c,d]=nums(s);return op==='ADD'?[p*d+c*q,q*d]:op==='MINUS'?[p*d-c*q,q*d]:op==='MULTIPLY'?[p*c,q*d]:[p*d,q*c];},['Učitaj brojilac i imenilac drugog razlomka.','Prilikom sabiranja i oduzimanja koristi unakrsne proizvode; pri dijeljenju pomnoži recipročnom vrijednošću.','Ispiši oba dijela rezultata u dva reda.']);});
F('zbir-visekratnika',6,'Petlje','Zbir odabranih višekratnika',k=>task(`djelilac ${k+1}`,`Učitaj granicu n od 1 do 30. Saberi prirodne brojeve od 1 do n djeljive sa ${k+1} i ispiši zbir.`,seq(S('n',read('Gornja granica')),S('zbir',N(0)),FOR('i',N(1),V('n'),N(1),IF(C('EQ',mod(V('i'),N(k+1)),N(0)),INC('zbir',V('i')))),P(V('zbir'))),[line(20),line(1),line(30)],s=>Array.from({length:Number(s)},(_,i)=>i+1).filter(n=>n%(k+1)===0).reduce((a,b)=>a+b,0)));
F('uzastopni-proizvod',6,'Petlje','Proizvod uzastopnih brojeva',k=>task(`početak ${k}`,`Učitaj broj činilaca n od 1 do 6. Izračunaj proizvod n uzastopnih prirodnih brojeva počevši od ${k}, tj. ${k} · (${k}+1) · … .`,seq(S('n',read('Broj činilaca')),S('proizvod',N(1)),FOR('i',N(k),sub(add(N(k),V('n')),N(1)),N(1),S('proizvod',mul(V('proizvod'),V('i')))),P(V('proizvod'))),[line(3),line(1),line(5)],s=>Array.from({length:Number(s)},(_,i)=>k+i).reduce((a,b)=>a*b,1)));
F('stepen-ponavljanjem',6,'Petlje','Stepen bez gotovog bloka',k=>task(`osnova ${k+1}`,`Učitaj nenegativan eksponent od 0 do 6. Izračunaj (${k+1})^eksponent ponovljenim množenjem. Za eksponent 0 rezultat je 1.`,seq(S('n',read('Eksponent')),S('rezultat',N(1)),REPEAT(V('n'),S('rezultat',mul(V('rezultat'),N(k+1)))),P(V('rezultat'))),[line(3),line(0),line(5)],s=>(k+1)**Number(s)));
F('zbir-ulazne-liste',6,'Liste','Zbir serije ulaznih mjerenja',k=>{const count=k+2;return task(`${count} mjerenja`,`Učitaj tačno ${count} brojeva, svaki u novom redu. Sačuvaj ih u listu i zatim petljom izračunaj i ispiši zbir.`,seq(readFixed(count),S('zbir',N(0)),FOR('j',N(1),N(count),N(1),INC('zbir',at(V('brojevi'),V('j')))),P(V('zbir'))),[line(Array.from({length:count},(_,i)=>i+1)),line(Array(count).fill(0)),line(Array.from({length:count},(_,i)=>i%2?-(i+1):i+1))],s=>nums(s).reduce((a,b)=>a+b,0));});
F('brojac-praga',6,'Liste','Koliko mjerenja prelazi prag?',k=>task(`prag ${k*3}`,`Prvi red je broj mjerenja n od 1 do 12, zatim slijedi n brojeva. Prebroj vrijednosti strogo veće od ${k*3} i ispiši njihov broj.`,seq(readDynamic(),S('brojac',N(0)),FOR('j',N(1),V('n'),N(1),IF(C('GT',at(V('brojevi'),V('j')),N(k*3)),INC('brojac',N(1)))),P(V('brojac'))),[line(4,k*3-1,k*3,k*3+1,k*3+5),line(2,0,1),line(3,k*3+1,k*3+2,k*3+3)],s=>nums(s).slice(1).filter(n=>n>k*3).length));

// 7. razred: number algorithms, sequences, coordinates and strings.
F('nzd',7,'Brojevni algoritmi','NZD sa zadanim ciklusom',k=>task(`ciklus ${6*(k+1)}`,`Učitaj pozitivan cijeli broj. Euklidovim algoritmom izračunaj NZD tog broja i ciklusa ${6*(k+1)}.`,seq(S('a',read('Broj')),S('b',N(6*(k+1))),gcdBlocks(),P(V('a'))),[line(18*(k+1)),line(7),line(6*(k+1))],s=>gcd(Number(s),6*(k+1)),['Postavi a na unos, b na zadani ciklus.','Dok b nije 0, zamijeni (a,b) sa (b,a mod b).','Završna vrijednost a je NZD.']));
F('nzs',7,'Brojevni algoritmi','NZS rasporeda',k=>task(`drugi ciklus ${5*(k+1)}`,`Učitaj pozitivan period prve aktivnosti. Druga se ponavlja svakih ${5*(k+1)} jedinica. Izračunaj NZS kao proizvod perioda podijeljen njihovim NZD-om.`,seq(S('a',read('Prvi period')),S('b',N(5*(k+1))),S('proizvod',mul(V('a'),V('b'))),gcdBlocks(),P(div(V('proizvod'),V('a')))),[line(12),line(5*(k+1)),line(7)],s=>Number(s)*5*(k+1)/gcd(Number(s),5*(k+1))));
F('prvi-prost',7,'Brojevni algoritmi','Prvi prost broj u intervalu',k=>{const end=25+k*5;return task(`gornja granica ${end}`,`Učitaj početak intervala n, 2 ≤ n ≤ ${end}. Ispiši prvi prost broj u [n, ${end}], ili 0 ako ga nema. Za svaki kandidat provjeri djelioca do njegovog kvadratnog korijena.`,seq(S('n',read('Početak')),S('rezultat',N(0)),FOR('kandidat',V('n'),N(end),N(1),IF(C('EQ',V('rezultat'),N(0)),seq(S('prost',N(1)),S('d',N(2)),WHILE(C('LTE',mul(V('d'),V('d')),V('kandidat')),IF(C('EQ',mod(V('kandidat'),V('d')),N(0)),S('prost',N(0))),INC('d',N(1))),IF(C('EQ',V('prost'),N(1)),S('rezultat',V('kandidat')))))),P(V('rezultat'))),[line(14),line(2),line(end)],s=>{for(let n=Number(s);n<=end;n++)if(isPrime(n))return n;return 0;},['Kandidat je prost ako nema djelilaca od 2 do √kandidata.','Rezultat postavi samo za prvi pronađeni prost broj.','Ako rezultat ostane 0, u traženom intervalu nema prostog broja.']);});
F('djelioci-interval',7,'Brojevni algoritmi','Broj djelilaca iznad granice',k=>task(`najmanji djelilac ${k}`,`Učitaj prirodan broj n ≥ ${k} i n ≤ 60. Prebroj njegove djelioce od ${k} do n i ispiši broj pronađenih djelilaca.`,seq(S('n',read('Prirodan broj')),S('brojac',N(0)),FOR('d',N(k),V('n'),N(1),IF(C('EQ',mod(V('n'),V('d')),N(0)),INC('brojac',N(1)))),P(V('brojac'))),[line(60),line(24),line(k+11)],s=>Array.from({length:Number(s)-k+1},(_,i)=>k+i).filter(d=>Number(s)%d===0).length));
F('zbir-cifara-osnove',7,'Brojevni sistemi','Zbir cifara u brojnom sistemu',k=>{const base=k+1;return task(`osnova ${base}`,`Učitaj nenegativan dekadni cijeli broj. Izračunaj zbir cifara njegovog zapisa u osnovi ${base}, bez pretvaranja unosa u tekst.`,seq(S('n',read('Dekadni broj')),S('zbir',N(0)),WHILE(C('GT',V('n'),N(0)),INC('zbir',mod(V('n'),N(base))),S('n',floor(div(V('n'),N(base))))),P(V('zbir'))),[line(45),line(0),line(101)],s=>{let n=Number(s),sum=0;while(n){sum+=n%base;n=Math.floor(n/base);}return sum;});});
F('obrnute-cifre',7,'Brojevni sistemi','Vrijednost obrnutih cifara',k=>{const base=k+1;return task(`osnova ${base}`,`Učitaj nenegativan dekadni broj. Obrni redoslijed njegovih cifara u osnovi ${base} i ispiši dekadnu vrijednost dobijenog zapisa. Početne nule obrnutog zapisa ne mijenjaju vrijednost.`,seq(S('n',read('Dekadni broj')),S('rezultat',N(0)),WHILE(C('GT',V('n'),N(0)),S('rezultat',add(mul(V('rezultat'),N(base)),mod(V('n'),N(base)))),S('n',floor(div(V('n'),N(base))))),P(V('rezultat'))),[line(45),line(0),line(base*base+base*2+1)],s=>{let n=Number(s),value=0;while(n){value=value*base+n%base;n=Math.floor(n/base);}return value;});});
F('iz-osnove',7,'Brojevni sistemi','Brojni zapis u dekadnu vrijednost',k=>{const base=[2,3,4,5,6,7,8,9,10,16][k-1],alphabet='0123456789ABCDEF';return task(`osnova ${base}`,`Učitaj validan brojni zapis u osnovi ${base}; za heksadecimalni zapis koristi velika slova A–F. Obradi cifre slijeva nadesno i ispiši dekadnu vrijednost.`,seq(S('zapis',readText('Brojni zapis')),S('vrijednost',N(0)),FOR('i',N(1),len(V('zapis')),N(1),S('cifra',sub(index(T(alphabet),char(V('zapis'),V('i'))),N(1))),S('vrijednost',add(mul(V('vrijednost'),N(base)),V('cifra')))),P(V('vrijednost'))),[(45).toString(base).toUpperCase(),'0',(101).toString(base).toUpperCase()],s=>parseInt(s,base));});
F('u-osnovu',7,'Brojevni sistemi','Dekadni broj u brojni zapis',k=>{const base=[2,3,4,5,6,7,8,9,10,16][k-1];return task(`osnova ${base}`,`Učitaj nenegativan dekadni cijeli broj. Pretvori ga u zapis u osnovi ${base} (velika slova A–F za osnovu 16). Broj 0 mora dati zapis „0“.`,seq(S('n',read('Dekadni broj')),S('zapis',T('')),IF(C('EQ',V('n'),N(0)),S('zapis',T('0'))),WHILE(C('GT',V('n'),N(0)),S('cifra',char(T('0123456789ABCDEF'),add(mod(V('n'),N(base)),N(1)))),S('zapis',join(V('cifra'),V('zapis'))),S('n',floor(div(V('n'),N(base))))),P(V('zapis'))),[line(45),line(0),line(101)],s=>Number(s).toString(base).toUpperCase());});
F('kvadratni-model',7,'Funkcije','Vrijednost kvadratnog modela',k=>task(`f(x) = ${k}x² + ${k+1}x + ${k+2}`,`Učitaj x i izračunaj f(x) = ${k}x² + ${k+1}x + ${k+2}. Upotrijebi Hornerov oblik (${k}x + ${k+1})x + ${k+2}.`,seq(S('x',read('x')),P(add(mul(add(mul(N(k),V('x')),N(k+1)),V('x')),N(k+2)))),[line(3),line(0),line(-2)],s=>k*Number(s)**2+(k+1)*Number(s)+k+2));
F('aritmeticki-zbir',7,'Nizovi','Zbir aritmetičkog niza',k=>task(`početak ${k}, razlika ${k+2}`,`Učitaj broj članova n od 1 do 15. Prvi član je ${k}, razlika ${k+2}. Petljom izračunaj zbir prvih n članova aritmetičkog niza.`,seq(S('n',read('Broj članova')),S('clan',N(k)),S('zbir',N(0)),REPEAT(V('n'),INC('zbir',V('clan')),INC('clan',N(k+2))),P(V('zbir'))),[line(5),line(1),line(8)],s=>Number(s)*(2*k+(Number(s)-1)*(k+2))/2));
F('geometrijski-zbir',7,'Nizovi','Zbir geometrijskog niza',k=>task(`početak ${k}, odnos 2`,`Učitaj broj članova od 1 do 10. Prvi član je ${k}, a svaki sljedeći je dvostruko veći. Petljom saberi i ispiši članove.`,seq(S('n',read('Broj članova')),S('clan',N(k)),S('zbir',N(0)),REPEAT(V('n'),INC('zbir',V('clan')),S('clan',mul(V('clan'),N(2)))),P(V('zbir'))),[line(5),line(1),line(8)],s=>k*(2**Number(s)-1)));
F('rekurentni-niz',7,'Nizovi','Niz zbira prethodna dva člana',k=>task(`početni članovi ${k-1} i ${k}`,`Učitaj poziciju n od 1 do 15. Niz počinje članovima ${k-1} i ${k}; svaki sljedeći član je zbir prethodna dva. Ispiši n-ti član.`,seq(S('n',read('Pozicija')),S('a',N(k-1)),S('b',N(k)),REPEAT(sub(V('n'),N(1)),S('sljedeci',add(V('a'),V('b'))),S('a',V('b')),S('b',V('sljedeci'))),P(V('a'))),[line(6),line(1),line(2)],s=>{let a=k-1,b=k;for(let i=1;i<Number(s);i++)[a,b]=[b,a+b];return a;}));
F('rast-do-cilja',7,'Petlje','Koliko udvostručavanja treba?',k=>task(`cilj ${100*k}`,`Učitaj pozitivnu početnu vrijednost. Udvostručavaj je dok ne dostigne barem ${100*k}. Ispiši broj udvostručavanja, pa završnu vrijednost.`,seq(S('vrijednost',read('Početna vrijednost')),S('brojac',N(0)),WHILE(C('LT',V('vrijednost'),N(100*k)),S('vrijednost',mul(V('vrijednost'),N(2))),INC('brojac',N(1))),P(V('brojac')),P(V('vrijednost'))),[line(3),line(100*k),line(25)],s=>{let value=Number(s),n=0;while(value<100*k){value*=2;n++;}return[n,value];}));
F('godisnji-rast',7,'Procenti','Simulacija ušteđevine',k=>task(`godišnji rast ${k}%`,`Učitaj početnu ušteđevinu i broj godina od 0 do 10 iz dva reda. Svake godine iznos raste ${k}%. Ispiši konačni iznos zaokružen na dvije decimale.`,seq(S('iznos',read('Početni iznos')),S('godine',read('Broj godina')),REPEAT(V('godine'),S('iznos',mul(V('iznos'),div(N(100+k),N(100))))),P(R2(V('iznos')))),[line(100,3),line(25,0),line(80,5)],s=>{const[a,n]=nums(s);return r2(a*((100+k)/100)**n);}));
F('translacija',7,'Geometrija','Pomjeranje koordinata',k=>task(`vektor (${k}, ${-2*k})`,`Učitaj x i y iz dva reda. Pomjeri tačku za vektor (${k}, ${-2*k}). Ispiši novu x pa novu y koordinatu.`,seq(S('x',read('x')),S('y',read('y')),P(add(V('x'),N(k))),P(sub(V('y'),N(2*k)))),[line(3,8),line(0,0),line(-5,-3)],s=>{const[x,y]=nums(s);return[x+k,y-2*k];}));
F('rastojanje-tacke',7,'Geometrija','Rastojanje do kontrolne tačke',k=>task(`tačka (${k}, ${k+2})`,`Učitaj x i y. Izračunaj rastojanje tačke (x,y) do (${k}, ${k+2}), pomoću √((x−${k})² + (y−${k+2})²). Ispiši rezultat zaokružen na dvije decimale.`,seq(S('x',read('x')),S('y',read('y')),P(R2(sqrt(add(pow(sub(V('x'),N(k)),N(2)),pow(sub(V('y'),N(k+2)),N(2))))))),[line(k+3,k+6),line(k,k+2),line(k-5,k+2)],s=>{const[x,y]=nums(s);return r2(Math.hypot(x-k,y-k-2));}));
F('brojanje-slova',7,'Tekst','Brojanje znakova iz odabrane grupe',k=>{const groups=['aeiou','AEIOU','0123456789','abc','xyz','+-*/','.,!?','čćšđž','ABCDEF','()[]{}'];const group=groups[k-1];return task(`grupa „${group}“`,`Učitaj tekst. Prebroj znakove koji pripadaju grupi „${group}“. Poređenje razlikuje velika i mala slova. Ispiši broj.`,seq(S('tekst',readText('Tekst')),S('brojac',N(0)),FOR('i',N(1),len(V('tekst')),N(1),IF(C('GT',index(T(group),char(V('tekst'),V('i'))),N(0)),INC('brojac',N(1)))),P(V('brojac'))),[group+' test', 'ELDI 123', group[0].repeat(3)],s=>[...s].filter(c=>group.includes(c)).length);});
F('zamjena-znaka',7,'Tekst','Zamjena svih odabranih znakova',k=>{const from='abcdefghij'[k-1],to='ABCDEFGHIJ'[k-1];return task(`${from} → ${to}`,`Učitaj tekst. Prođi kroz njegove znakove i svako malo slovo „${from}“ zamijeni velikim „${to}“. Ostali znakovi ostaju isti.`,seq(S('tekst',readText('Tekst')),S('rezultat',T('')),FOR('i',N(1),len(V('tekst')),N(1),S('znak',char(V('tekst'),V('i'))),IF(C('EQ',V('znak'),T(from)),S('znak',T(to))),S('rezultat',join(V('rezultat'),V('znak')))),P(V('rezultat'))),[from+' '+from+from,'programiranje','ELDI'],s=>s.split(from).join(to));});
F('format-duzine',7,'Tekst','Formatiranje prema dužini',k=>task(`granica ${k+3} znakova`,`Učitaj tekst. Ako ima najviše ${k+3} znakova, ispiši ga velikim slovima; ako je duži, ispiši ga malim slovima.`,seq(S('tekst',readText('Tekst')),IF(C('LTE',len(V('tekst')),N(k+3)),P(B('text_changeCase',{CASE:'UPPERCASE'},{TEXT:V('tekst')})),P(B('text_changeCase',{CASE:'LOWERCASE'},{TEXT:V('tekst')})))),['Eldi','PROGRAMIRANJE','aBc'],s=>s.length<=k+3?s.toUpperCase():s.toLowerCase()));
F('trazenje-teksta',7,'Tekst','Prva pozicija obrasca',k=>{const needle=['EDU','AI','MAT','PY','CPP','JAVA','BLOK','TEST','KOD','ELDI'][k-1];return task(`obrazac ${needle}`,`Učitaj tekst i pronađi prvo pojavljivanje obrasca „${needle}“. Pozicije počinju od 1. Ispiši 0 ako obrasca nema.`,seq(S('tekst',readText('Tekst')),P(index(V('tekst'),T(needle)))),['xx'+needle+'yy'+needle,needle,'nema obrasca'],s=>s.indexOf(needle)+1);});

// 8. razred: list/matrix algorithms with different declared data dimensions.
for(const [id,title,op] of [['minimum-liste','Najmanje mjerenje liste','LT'],['maksimum-liste','Najveće mjerenje liste','GT']])F(id,8,'Liste',title,k=>{const n=k+2;return task(`${n} mjerenja`,`Učitaj tačno ${n} brojeva iz ${n} redova. Jednim prolazom kroz listu nađi i ispiši ${op==='LT'?'najmanji':'najveći'} element.`,seq(readFixed(n),S('rezultat',at(V('brojevi'),N(1))),FOR('j',N(2),N(n),N(1),IF(C(op,at(V('brojevi'),V('j')),V('rezultat')),S('rezultat',at(V('brojevi'),V('j'))))),P(V('rezultat'))),[line(Array.from({length:n},(_,i)=>i%2?-i:i+4)),line(Array(n).fill(7)),line(Array.from({length:n},(_,i)=>-i-2))],s=>(op==='LT'?Math.min:Math.max)(...nums(s)));});
F('prosjek-liste',8,'Statistika','Prosjek serije mjerenja',k=>{const n=k+2;return task(`${n} mjerenja`,`Učitaj ${n} brojeva. Sačuvaj ih u listu, saberi i izračunaj aritmetički prosjek pomoću dužine liste. Ispiši prosjek zaokružen na dvije decimale.`,seq(readFixed(n),S('zbir',N(0)),FOR('j',N(1),llen(V('brojevi')),N(1),INC('zbir',at(V('brojevi'),V('j')))),P(R2(div(V('zbir'),llen(V('brojevi')))))),[line(Array.from({length:n},(_,i)=>i+1)),line(Array(n).fill(4)),line(Array.from({length:n},(_,i)=>i%2?-i:i))],s=>r2(nums(s).reduce((a,b)=>a+b,0)/n));});
F('djeljivi-u-listi',8,'Liste','Filtriranje liste po djeljivosti',k=>task(`djelilac ${k+2}`,`Učitaj broj elemenata n (1–12), zatim n cijelih brojeva. Ispiši samo elemente djeljive sa ${k+2}, u originalnom redoslijedu; ako nijedan ne odgovara, konzola ostaje prazna.`,seq(readDynamic(),FOR('j',N(1),V('n'),N(1),IF(C('EQ',mod(at(V('brojevi'),V('j')),N(k+2)),N(0)),P(at(V('brojevi'),V('j')))))),[line(4,k+2,1,2*(k+2),3),line(2,1,1),line(3,0,-(k+2),k+2)],s=>nums(s).slice(1).filter(n=>n%(k+2)===0)));
F('linearno-trazenje',8,'Pretraživanje','Linearno pretraživanje',k=>task(`cilj ${k*3}`,`Učitaj broj elemenata n (1–12), zatim n cijelih brojeva. Nađi prvu poziciju broja ${k*3}. Pozicije počinju od 1; ispiši 0 ako ga nema.`,seq(readDynamic(),S('pozicija',N(0)),FOR('j',N(1),V('n'),N(1),IF(and(C('EQ',at(V('brojevi'),V('j')),N(k*3)),C('EQ',V('pozicija'),N(0))),S('pozicija',V('j')))),P(V('pozicija'))),[line(4,1,k*3,2,k*3),line(3,0,-1,2),line(1,k*3)],s=>nums(s).slice(1).indexOf(k*3)+1));
F('binarno-trazenje',8,'Pretraživanje','Binarno pretraživanje',k=>task(`cilj ${k*4}`,`Učitaj broj elemenata n (1–15), zatim strogo rastuću listu od n cijelih brojeva. Binarnim pretraživanjem pronađi ${k*4}. Ispiši poziciju od 1, ili 0 ako cilja nema.`,seq(readDynamic(),S('lijevo',N(1)),S('desno',V('n')),S('pozicija',N(0)),WHILE(and(C('LTE',V('lijevo'),V('desno')),C('EQ',V('pozicija'),N(0))),S('sredina',floor(div(add(V('lijevo'),V('desno')),N(2)))),IF(C('EQ',at(V('brojevi'),V('sredina')),N(k*4)),S('pozicija',V('sredina')),IF(C('LT',at(V('brojevi'),V('sredina')),N(k*4)),S('lijevo',add(V('sredina'),N(1))),S('desno',sub(V('sredina'),N(1)))))),P(V('pozicija'))),[line(5,0,k*4-1,k*4,k*4+1,k*4+9),line(3,0,1,2),line(1,k*4)],s=>nums(s).slice(1).indexOf(k*4)+1,['Čuvaj lijevu i desnu granicu liste.','Poredi cilj sa središnjim elementom i odbaci odgovarajuću polovinu.','Vrati poziciju pronađenog elementa ili 0.']));
F('bubble-sort',8,'Sortiranje','Sortiranje zamjenom susjeda',k=>{const n=k+2;return task(`${n} elemenata`,`Učitaj ${n} cijelih brojeva. Sortiraj ih uzlazno poređenjem susjednih elemenata i zamjenom kada su u pogrešnom redoslijedu. Ispiši svaki element u novom redu.`,seq(readFixed(n),sortBlocks(),FOR('i',N(1),N(n),N(1),P(at(V('brojevi'),V('i'))))),[line(Array.from({length:n},(_,i)=>n-i)),line(Array.from({length:n},(_,i)=>i%3)),line(Array.from({length:n},(_,i)=>i%2?-i:i))],s=>nums(s).sort((a,b)=>a-b),['Učitaj elemente u listu.','Ponovi prolaze kroz susjedne parove, uz privremenu varijablu za zamjenu.','Ispiši uređenu listu i isprobaj duplikate.']);});
F('selection-sort',8,'Sortiranje','Sortiranje izborom minimuma',k=>{const n=k+2;return task(`${n} elemenata`,`Učitaj ${n} cijelih brojeva. Za svaku poziciju pronađi najmanji element preostalog dijela i zamijeni ga na tu poziciju. Ispiši sortiranu listu.`,seq(readFixed(n),FOR('i',N(1),N(n-1),N(1),S('najmanja',V('i')),FOR('j',add(V('i'),N(1)),N(n),N(1),IF(C('LT',at(V('brojevi'),V('j')),at(V('brojevi'),V('najmanja'))),S('najmanja',V('j')))),S('privremeni',at(V('brojevi'),V('i'))),put(V('brojevi'),V('i'),at(V('brojevi'),V('najmanja'))),put(V('brojevi'),V('najmanja'),V('privremeni'))),FOR('i',N(1),N(n),N(1),P(at(V('brojevi'),V('i'))))),[line(Array.from({length:n},(_,i)=>n-i)),line(Array.from({length:n},(_,i)=>i%3)),line(Array.from({length:n},(_,i)=>i%2?-i:i))],s=>nums(s).sort((a,b)=>a-b));});
F('prefiksni-zbirovi',8,'Liste','Kumulativni zbir mjerenja',k=>{const n=k+2;return task(`${n} mjerenja`,`Učitaj ${n} brojeva. Ispiši n prefiksnih zbirova: prvi element, zbir prva dva, zbir prva tri i tako dalje.`,seq(readFixed(n),S('zbir',N(0)),FOR('j',N(1),N(n),N(1),INC('zbir',at(V('brojevi'),V('j'))),P(V('zbir')))),[line(Array.from({length:n},(_,i)=>i+1)),line(Array(n).fill(0)),line(Array.from({length:n},(_,i)=>i%2?-2:3))],s=>{let sum=0;return nums(s).map(v=>sum+=v);});});
F('pokretni-prosjek',8,'Statistika','Pokretni prosjek',k=>{const w=k+1,n=w+3;return task(`prozor ${w}`,`Učitaj ${n} mjerenja. Za svaki uzastopni prozor dužine ${w}, izračunaj prosjek i ispiši ga zaokruženog na dvije decimale. Biće ${n-w+1} izlazna reda.`,seq(readFixed(n),FOR('i',N(1),N(n-w+1),N(1),S('zbir',N(0)),FOR('j',V('i'),add(V('i'),N(w-1)),N(1),INC('zbir',at(V('brojevi'),V('j')))),P(R2(div(V('zbir'),N(w)))))),[line(Array.from({length:n},(_,i)=>i+1)),line(Array(n).fill(5)),line(Array.from({length:n},(_,i)=>i%2?-3:4))],s=>{const a=nums(s);return Array.from({length:n-w+1},(_,i)=>r2(a.slice(i,i+w).reduce((x,y)=>x+y,0)/w));});});
F('frekvencija-cilja',8,'Statistika','Frekvencija ciljane vrijednosti',k=>task(`cilj ${k}`,`Učitaj n (1–12), zatim n brojeva. Prebroj koliko je elemenata jednako ${k}. Ispiši broj pojavljivanja i relativnu frekvenciju u procentima, zaokruženu na dvije decimale.`,seq(readDynamic(),S('brojac',N(0)),FOR('j',N(1),V('n'),N(1),IF(C('EQ',at(V('brojevi'),V('j')),N(k)),INC('brojac',N(1)))),P(V('brojac')),P(R2(div(mul(V('brojac'),N(100)),V('n'))))),[line(5,k,0,k,2*k,k),line(3,0,0,0),line(2,k,k)],s=>{const a=nums(s),count=a.slice(1).filter(n=>n===k).length;return[count,r2(count*100/a[0])];}));
F('jedinstvene-vrijednosti',8,'Liste','Izdvajanje bez duplikata',k=>{const n=k+2;return task(`${n} elemenata`,`Učitaj ${n} cijelih brojeva. Napravi novu listu u kojoj je svaki različiti broj samo jednom, prema redoslijedu prvog pojavljivanja. Ispiši novu listu.`,seq(readFixed(n),S('jedinstveni',L()),FOR('j',N(1),N(n),N(1),S('vrijednost',at(V('brojevi'),V('j'))),IF(C('EQ',B('lists_indexOf',{END:'FIRST'},{VALUE:V('jedinstveni'),FIND:V('vrijednost')}),N(0)),append(V('jedinstveni'),V('vrijednost')))),FOR('j',N(1),llen(V('jedinstveni')),N(1),P(at(V('jedinstveni'),V('j'))))),[line(Array.from({length:n},(_,i)=>i%3)),line(Array(n).fill(7)),line(Array.from({length:n},(_,i)=>i))],s=>[...new Set(nums(s))]);});
F('medijan-liste',8,'Statistika','Medijan nakon sortiranja',k=>{const n=2*k+1;return task(`${n} elemenata`,`Učitaj ${n} cijelih brojeva. Sortiraj listu i ispiši medijan, tj. element na poziciji ${k+1}.`,seq(readFixed(n),sortBlocks(),P(at(V('brojevi'),N(k+1)))),[line(Array.from({length:n},(_,i)=>n-i)),line(Array(n).fill(4)),line(Array.from({length:n},(_,i)=>i-k))],s=>nums(s).sort((a,b)=>a-b)[k]);});
F('filter-intervala',8,'Liste','Elementi iz intervala',k=>task(`interval [${k}, ${k+5}]`,`Učitaj n (1–12), zatim n brojeva. Ispiši samo elemente zatvorenog intervala [${k}, ${k+5}] u originalnom redoslijedu.`,seq(readDynamic(),FOR('j',N(1),V('n'),N(1),S('vrijednost',at(V('brojevi'),V('j'))),IF(and(C('GTE',V('vrijednost'),N(k)),C('LTE',V('vrijednost'),N(k+5))),P(V('vrijednost'))))),[line(5,k-1,k,k+3,k+5,k+6),line(3,0,-2,-4),line(2,k,k+5)],s=>nums(s).slice(1).filter(v=>v>=k&&v<=k+5)));
F('transformacija-liste',8,'Funkcije','Afina transformacija podataka',k=>task(`y = ${k+1}x − ${k}`,`Učitaj n (1–12), zatim n brojeva. Za svaki x izračunaj i ispiši y = ${k+1}x − ${k}.`,seq(readDynamic(),FOR('j',N(1),V('n'),N(1),P(sub(mul(N(k+1),at(V('brojevi'),V('j'))),N(k))))),[line(4,0,1,3,-2),line(1,0),line(3,5,5,5)],s=>nums(s).slice(1).map(v=>(k+1)*v-k)));
F('skalarni-proizvod',8,'Vektori i matrice','Skalarni proizvod vektora',k=>{const n=k+1;return task(`dimenzija ${n}`,`Učitaj ${n} koordinata prvog vektora, zatim ${n} koordinata drugog, sve u zasebnim redovima. Ispiši skalarni proizvod: zbir proizvoda odgovarajućih koordinata.`,seq(readFixed(n,'prvi'),readFixed(n,'drugi'),S('zbir',N(0)),FOR('j',N(1),N(n),N(1),INC('zbir',mul(at(V('prvi'),V('j')),at(V('drugi'),V('j'))))),P(V('zbir'))),[line(Array.from({length:n},(_,i)=>i+1),Array(n).fill(2)),line(Array(n).fill(0),Array(n).fill(3)),line(Array.from({length:n},(_,i)=>i-2),Array.from({length:n},(_,i)=>2-i))],s=>{const a=nums(s);return a.slice(0,n).reduce((sum,v,i)=>sum+v*a[n+i],0);});});
