F('zbirovi-redova',8,'Vektori i matrice','Zbir svakog reda matrice',k=>{const rows=k+1,cols=3;return task(`${rows} reda, 3 kolone`,`Učitaj ${rows*cols} brojeva matrice sa ${rows} redova i 3 kolone, red po red. Ispiši ${rows} rednih zbirova.`,seq(readFixed(rows*cols),FOR('r',N(1),N(rows),N(1),S('zbir',N(0)),FOR('c',N(1),N(cols),N(1),INC('zbir',at(V('brojevi'),add(mul(sub(V('r'),N(1)),N(cols)),V('c'))))),P(V('zbir')))),[line(Array.from({length:rows*cols},(_,i)=>i+1)),line(Array(rows*cols).fill(2)),line(Array.from({length:rows*cols},(_,i)=>i%2?1:-1))],s=>{const a=nums(s);return Array.from({length:rows},(_,i)=>a.slice(i*cols,(i+1)*cols).reduce((a,b)=>a+b,0));});});
F('filter-dva-uzorka',8,'Liste','Filter susjednih uzoraka',k=>task(`težine ${k} i ${k+1}`,`Učitaj n (2–12), zatim n brojeva. Za svaki susjedni par (a_i,a_(i+1)) ispiši ${k}·a_i + ${k+1}·a_(i+1). Izlaz ima n−1 redova.`,seq(readDynamic(),FOR('j',N(1),sub(V('n'),N(1)),N(1),P(add(mul(N(k),at(V('brojevi'),V('j'))),mul(N(k+1),at(V('brojevi'),add(V('j'),N(1)))))))),[line(4,1,2,3,4),line(2,0,0),line(3,-1,2,-3)],s=>{const a=nums(s).slice(1);return a.slice(0,-1).map((v,i)=>k*v+(k+1)*a[i+1]);}));
F('horner-koeficijenti',8,'Funkcije','Hornerovo računanje polinoma',k=>{const count=k+2;return task(`${count} koeficijenata`,`Učitaj x, zatim ${count} koeficijenata polinoma od najvišeg stepena prema konstantnom članu. Hornerovim postupkom izračunaj i ispiši vrijednost polinoma u x.`,seq(S('x',read('x')),S('vrijednost',N(0)),REPEAT(N(count),S('koeficijent',read('Koeficijent')),S('vrijednost',add(mul(V('vrijednost'),V('x')),V('koeficijent')))),P(V('vrijednost'))),[line(2,Array.from({length:count},(_,i)=>i+1)),line(0,Array.from({length:count},(_,i)=>i+1)),line(1,Array(count).fill(1))],s=>{const[x,...a]=nums(s);return a.reduce((sum,c,i)=>sum+c*x**(count-1-i),0);});});

// 9. razred: procedures/events, coding and numerical models.
const defineReturn=(name,params,RETURN,body)=>B('procedures_defreturn',{NAME:name},{...(body?{STACK:body}:{}),RETURN},{params:params.map(n=>({name:n,id:'v-'+n}))});
const callReturn=(name,params,args)=>B('procedures_callreturn',{},Object.fromEntries(args.map((v,i)=>['ARG'+i,v])),{name,params});
const defineNoReturn=(name,params,STACK)=>B('procedures_defnoreturn',{NAME:name},{STACK},{params:params.map(n=>({name:n,id:'v-'+n}))});
const callNoReturn=(name,params,args)=>B('procedures_callnoreturn',{},Object.fromEntries(args.map((v,i)=>['ARG'+i,v])),{name,params});
F('funkcija-afina',9,'Funkcije i postupci','Funkcija jednog argumenta',k=>task(`f(x) = ${k+1}x + ${k}`,`Definiši funkciju f(x) koja vraća ${k+1}x + ${k}. Učitaj x i ispiši f(x), zatim f(x+1). Računanje mora biti u funkciji koja se poziva dva puta.`,[defineReturn('model',['argument'],add(mul(N(k+1),V('argument')),N(k))),seq(S('x',read('x')),P(callReturn('model',['argument'],[V('x')])),P(callReturn('model',['argument'],[add(V('x'),N(1))])))],[line(3),line(0),line(-2)],s=>[(k+1)*Number(s)+k,(k+1)*(Number(s)+1)+k],['Definiši funkciju sa jednim parametrom i povratnom vrijednošću.','Učitaj x u glavnom programu.','Pozovi funkciju za x i x+1, bez kopiranja njenog izraza.']));
F('funkcija-norma',9,'Funkcije i postupci','Funkcija dva argumenta',k=>task(`f(a,b) = ${k}a² + b²`,`Definiši funkciju f(a,b) koja vraća ${k}a² + b². Učitaj a i b, pa ispiši f(a,b) i f(b,a) u dva reda.`,[defineReturn('norma',['prvi','drugi'],add(mul(N(k),pow(V('prvi'),N(2))),pow(V('drugi'),N(2)))),seq(S('a',read('a')),S('b',read('b')),P(callReturn('norma',['prvi','drugi'],[V('a'),V('b')])),P(callReturn('norma',['prvi','drugi'],[V('b'),V('a')])))],[line(3,4),line(0,2),line(-2,5)],s=>{const[a,b]=nums(s);return[k*a*a+b*b,k*b*b+a*a];}));
F('funkcija-nzd',9,'Funkcije i postupci','NZD kao funkcija',k=>task(`referentni broj ${k*12}`,`Definiši funkciju za NZD dva pozitivna broja Euklidovim postupkom. Učitaj n i ispiši NZD(n,${k*12}), zatim NZD(n,${k*12+6}), koristeći istu funkciju.`,[defineReturn('nzd',['a','b'],V('a'),gcdBlocks()),seq(S('n',read('n')),P(callReturn('nzd',['a','b'],[V('n'),N(k*12)])),P(callReturn('nzd',['a','b'],[V('n'),N(k*12+6)])))],[line(18),line(7),line(24)],s=>[gcd(Number(s),k*12),gcd(Number(s),k*12+6)]));
F('postupak-pravougaonika',9,'Funkcije i postupci','Više oblika jednim postupkom',k=>{const count=k+1;return task(`${count} pravougaonika`,`Definiši postupak koji jednom petljom crta pravougaonik širine w i visine h. Učitaj w i h od 5 do 25. Počni na x=${-15*count}, y=0 da sve kopije budu vidljive. Pozovi postupak ${count} puta, a poslije svake kopije pomjeri se 30 koraka desno bez traga. Ispiši broj nacrtanih duži.`,[defineNoReturn('pravougaonik',['w','h'],REPEAT(N(2),move(V('w')),turn(N(90)),move(V('h')),turn(N(90)))),seq(S('sirina',read('Širina')),S('visina',read('Visina')),pen(false),go(N(-count*15),N(0)),pen(true),REPEAT(N(count),callNoReturn('pravougaonik',['w','h'],[V('sirina'),V('visina')]),pen(false),move(N(30)),pen(true)),P(N(count*4)))],[line(10,15),line(5,5),line(20,10)],()=>count*4,['Postupak prima širinu i visinu kao parametre.','Kretanje između oblika obavljaj s podignutom olovkom.','Broj duži mora biti četiri puta broj kopija.'],{stage:s=>({type:'stage',x:count*15,y:0,heading:0,trailCount:count*4,segmentLengths:Array.from({length:count},()=>[nums(s)[0],nums(s)[1],nums(s)[0],nums(s)[1]]).flat(),segmentAngles:Array.from({length:count},()=>[0,-90,180,90]).flat()})});});
F('poruka-racunanje',9,'Događaji','Računanje na primljenu poruku',k=>task(`poruka račun-${k}`,`Učitaj broj a. Registruj prijem poruke „račun-${k}“ koji računa ${k+1}a + ${k}. Pošalji poruku dva puta: prvo za a, zatim za a+1. Ispiši dva rezultata kroz prijem poruke.`,[B('edu_received',{MESSAGE:`račun-${k}`},{DO:P(add(mul(N(k+1),V('a')),N(k)))}),seq(S('a',read('a')),B('edu_message',{},{TEXT:T(`račun-${k}`)}),INC('a',N(1)),B('edu_message',{},{TEXT:T(`račun-${k}`)}))],[line(3),line(0),line(-2)],s=>[(k+1)*Number(s)+k,(k+1)*(Number(s)+1)+k]));
F('poruka-crtanje',9,'Događaji','Crtež pokrenut porukom',k=>{const sides=k+3;return task(`${sides}-ugao`,`Učitaj stranicu od 5 do 20. Pošalji poruku „crtaj-${sides}“. U prijemu poruke nacrtaj pravilni ${sides}-ugao i ispiši njegov obim.`,[B('edu_received',{MESSAGE:`crtaj-${sides}`},{DO:seq(REPEAT(N(sides),move(V('a')),turn(div(N(360),N(sides)))),P(mul(V('a'),N(sides))))}),seq(S('a',read('Stranica')),B('edu_message',{},{TEXT:T(`crtaj-${sides}`)}))],[line(10),line(15),line(20)],s=>Number(s)*sides,undefined,{stage:s=>({type:'stage',x:0,y:0,heading:360,trailCount:sides,closed:true,segmentLengths:Array(sides).fill(Number(s)),segmentAngles:Array.from({length:sides},(_,i)=>-i*360/sides)})});});
F('cezar-sifra',9,'Kodiranje','Cezarova šifra',k=>task(`pomak ${k}`,`Učitaj tekst sastavljen samo od velikih engleskih slova A–Z. Pomjeri svako slovo za ${k} mjesta unaprijed, sa povratkom poslije Z na A. Ispiši šifrovani tekst.`,seq(S('tekst',readText('A-Z')),S('abeceda',T('ABCDEFGHIJKLMNOPQRSTUVWXYZ')),S('rezultat',T('')),FOR('i',N(1),len(V('tekst')),N(1),S('pozicija',sub(index(V('abeceda'),char(V('tekst'),V('i'))),N(1))),S('nova',add(mod(add(V('pozicija'),N(k)),N(26)),N(1))),S('rezultat',join(V('rezultat'),char(V('abeceda'),V('nova'))))),P(V('rezultat'))),['ELDI','XYZ','ABC'],s=>[...s].map(c=>String.fromCharCode(65+(c.charCodeAt(0)-65+k)%26)).join('')));
F('provjera-lozinke',9,'Tekst','Pravila za školsku lozinku',k=>{const min=k+3;return task(`najmanje ${min} znakova`,`Učitaj lozinku sastavljenu od ASCII slova i cifara. Valjana je ako ima barem ${min} znakova, barem jedno veliko slovo A–Z i barem jednu cifru 0–9. Ispiši „valjana“ ili „nevaljana“. Ovo je vježba uslova, ne sistem za stvarne korisničke račune.`,seq(S('tekst',readText('Lozinka za vježbu')),S('veliko',N(0)),S('cifra',N(0)),FOR('i',N(1),len(V('tekst')),N(1),S('znak',char(V('tekst'),V('i'))),IF(C('GT',index(T('ABCDEFGHIJKLMNOPQRSTUVWXYZ'),V('znak')),N(0)),S('veliko',N(1))),IF(C('GT',index(T('0123456789'),V('znak')),N(0)),S('cifra',N(1)))),IF(and(C('GTE',len(V('tekst')),N(min)),and(C('EQ',V('veliko'),N(1)),C('EQ',V('cifra'),N(1)))),P(T('valjana')),P(T('nevaljana')))),['A1'+'a'.repeat(min), 'a'.repeat(min+1),'AB1'],s=>s.length>=min&&/[A-Z]/.test(s)&&/[0-9]/.test(s)?'valjana':'nevaljana');});
F('rle-paketi',9,'Kodiranje','Kodiranje ponovljenih znakova u paketima',k=>{const cap=k+1;return task(`paket do ${cap} znakova`,`Učitaj neprazan ASCII tekst. Spoji uzastopne jednake znakove u pakete od najviše ${cap} znakova. Za svaki paket ispiši „znak:broj“ u novom redu. Duga ponavljanja podijeli na više paketa.`,seq(S('tekst',readText('Neprazan tekst')),S('znak',char(V('tekst'),N(1))),S('brojac',N(1)),IF(C('GT',len(V('tekst')),N(1)),FOR('i',N(2),len(V('tekst')),N(1),S('novi',char(V('tekst'),V('i'))),IF(and(C('EQ',V('novi'),V('znak')),C('LT',V('brojac'),N(cap))),INC('brojac',N(1)),seq(P(join(V('znak'),T(':'),V('brojac'))),S('znak',V('novi')),S('brojac',N(1)))))),P(join(V('znak'),T(':'),V('brojac')))),['A'.repeat(cap+2)+'BBCCC','X','ABAB'],s=>{const result=[];let i=0;while(i<s.length){let j=i+1;while(j<s.length&&s[j]===s[i]&&j-i<cap)j++;result.push(`${s[i]}:${j-i}`);i=j;}return result;});});
F('izvod-polinoma',9,'Funkcije','Vrijednost izvoda polinoma',k=>{const degree=k+1;return task(`stepen ${degree}`,`Učitaj x, zatim ${degree+1} koeficijenata polinoma od stepena ${degree} do konstantnog člana. Izračunaj p′(x) pomoću Hornerovog postupka na izvedenim koeficijentima. Ispiši vrijednost. Dodatna tema za napredne učenike.`,seq(S('x',read('x')),S('vrijednost',N(0)),FOR('d',N(degree),N(1),N(1),S('koeficijent',read('Koeficijent')),S('vrijednost',add(mul(V('vrijednost'),V('x')),mul(V('koeficijent'),V('d'))))),S('konstanta',read('Konstantni član')),P(V('vrijednost'))),[line(2,Array(degree+1).fill(1)),line(0,Array.from({length:degree+1},(_,i)=>i+1)),line(1,Array.from({length:degree+1},(_,i)=>i%2?0:2))],s=>{const[x,...a]=nums(s);return a.slice(0,-1).reduce((sum,c,i)=>sum+c*(degree-i)*x**(degree-i-1),0);});});
F('newton-korijen',9,'Numerički modeli','Newtonova aproksimacija korijena',k=>{const iterations=k+2;return task(`${iterations} iteracija`,`Učitaj pozitivan broj n. Počni od x=n. Ponovi x ← (x + n/x)/2 tačno ${iterations} puta. Ispiši aproksimaciju √n zaokruženu na četiri decimale. Ovo je napredni numerički model.`,seq(S('n',read('n')),S('x',V('n')),REPEAT(N(iterations),S('x',div(add(V('x'),div(V('n'),V('x'))),N(2)))),P(R4(V('x')))),[line(2),line(1),line(9)],s=>{const n=Number(s);let x=n;for(let i=0;i<iterations;i++)x=.5*x+.5*n/x;return r4(x);});});
F('bisekcija-korijen',9,'Numerički modeli','Korijen sužavanjem intervala',k=>{const iterations=k+8;return task(`${iterations} koraka`,`Učitaj broj n ≥ 1. Traži √n u intervalu [0,n]. Tačno ${iterations} puta prepolovi interval i zadrži polovinu koja sadrži korijen. Ispiši sredinu završnog intervala na četiri decimale.`,seq(S('n',read('n')),S('lijevo',N(0)),S('desno',V('n')),REPEAT(N(iterations),S('sredina',div(add(V('lijevo'),V('desno')),N(2))),IF(C('LT',mul(V('sredina'),V('sredina')),V('n')),S('lijevo',V('sredina')),S('desno',V('sredina')))),P(R4(div(add(V('lijevo'),V('desno')),N(2))))),[line(2),line(1),line(9)],s=>{let a=0,b=Number(s);for(let i=0;i<iterations;i++){const x=(a+b)/2;if(x*x<Number(s))a=x;else b=x;}return r4((a+b)/2);});});
F('trapezna-integracija',9,'Numerički modeli','Površina ispod krive trapezima',k=>{const count=k+2;return task(`${count} trapeza`,`Učitaj pozitivnu gornju granicu b. Aproksimiraj površinu ispod y=x² na [0,b] sa ${count} jednakih trapeza. Ispiši zbir površina na četiri decimale. Napredna tema, geometrijska aproksimacija.`,seq(S('b',read('Gornja granica')),S('h',div(V('b'),N(count))),S('zbir',div(pow(V('b'),N(2)),N(2))),FOR('i',N(1),N(count-1),N(1),INC('zbir',pow(mul(V('i'),V('h')),N(2)))),P(R4(mul(V('zbir'),V('h'))))),[line(3),line(1),line(2)],s=>r4(Number(s)**3*(2*count*count+1)/(6*count*count)));});
F('budzet-prihod',9,'Simulacije','Mjesečni budžet sa izdvajanjima',k=>task(`izdvajanje ${k}%`,`Učitaj mjesečni prihod, zatim tri vrste troškova iz tri naredna reda. Od prihoda prvo izdvoji ${k}% za štednju. Ispiši ostatak nakon sva tri troška (dvije decimale), pa „pozitivan“ za ostatak ≥ 0 ili „minus“.`,seq(S('prihod',read('Prihod')),S('zbir',N(0)),REPEAT(N(3),INC('zbir',read('Trošak'))),S('ostatak',R2(sub(mul(V('prihod'),div(N(100-k),N(100))),V('zbir')))),P(V('ostatak')),IF(C('GTE',V('ostatak'),N(0)),P(T('pozitivan')),P(T('minus')))),[line(1000,200,150,100),line(100,80,30,20),line(0,0,0,0)],s=>{const[income,...cost]=nums(s),left=r2(income*(100-k)/100-cost.reduce((a,b)=>a+b,0));return[left,left>=0?'pozitivan':'minus'];}));
F('kvadratna-jednacina',9,'Jednačine','Korijeni kvadratne jednačine',k=>task(`koeficijent a=${k}`,`Učitaj b i c za jednačinu ${k}x²+bx+c=0. Ulaz mora imati pozitivnu diskriminantu. Ispiši prvo korijen sa +√D, zatim sa −√D, oba zaokružena na četiri decimale.`,seq(S('b',read('b')),S('c',read('c')),S('d',sub(pow(V('b'),N(2)),mul(N(4*k),V('c')))),S('korijen',sqrt(V('d'))),P(R4(div(add(mul(N(-1),V('b')),V('korijen')),N(2*k)))),P(R4(div(sub(mul(N(-1),V('b')),V('korijen')),N(2*k))))),[line(-5*k,6*k),line(k,-2*k),line(0,-4*k)],s=>{const[b,c]=nums(s),d=Math.sqrt(b*b-4*k*c);return[r4((-b+d)/(2*k)),r4((-b-d)/(2*k))];}));
F('linearni-sistem',9,'Jednačine','Sistem dvije linearne jednačine',k=>task(`${k}x+y=p; x−y=q`,`Učitaj p i q iz dva reda. Riješi sistem ${k}x+y=p i x−y=q. Ispiši x i y zaokružene na četiri decimale.`,seq(S('p',read('p')),S('q',read('q')),S('x',div(add(V('p'),V('q')),N(k+1))),S('y',sub(V('x'),V('q'))),P(R4(V('x'))),P(R4(V('y')))),[line(k*3+2,1),line(0,0),line(k-4,5)],s=>{const[p,q]=nums(s),x=(p+q)/(k+1);return[r4(x),r4(x-q)];}));
F('zvucni-niz',9,'Zvuk','Niz tonova i frekvencija',k=>task(`korak ${k*10} Hz`,`Učitaj početnu frekvenciju od 100 do 1000 Hz i broj tonova od 1 do 5. Za svaki sljedeći ton povećaj frekvenciju za ${k*10} Hz. Odsviraj svaki ton 0,05 s i ispiši njegovu frekvenciju.`,seq(S('f',read('Početna frekvencija')),S('n',read('Broj tonova')),REPEAT(V('n'),B('edu_tone',{},{FREQ:V('f'),DURATION:N(.05)}),P(V('f')),INC('f',N(k*10)))),[line(200,3),line(440,1),line(100,5)],s=>{const[f,n]=nums(s);return Array.from({length:n},(_,i)=>f+i*k*10);},undefined,{actions:s=>({type:'actions',counts:{tone:nums(s)[1]}})}));
F('zvjezdasti-poligon',9,'Pozornica','Zvjezdasti put sa preskakanjem vrha',k=>{const sides=2*k+3;return task(`${sides} vrhova, korak 2`,`Učitaj dužinu duži od 5 do 25. Nacrtaj zvjezdasti poligon sa ${sides} vrhova, okretanjem za 720/${sides} stepeni nakon svake duži. Ovo spaja svaki drugi vrh; broj vrhova je neparan. Ispiši ukupnu dužinu putanje.`,seq(S('a',read('Dužina duži')),REPEAT(N(sides),move(V('a')),turn(div(N(720),N(sides)))),P(mul(V('a'),N(sides)))),[line(10),line(15),line(20)],s=>Number(s)*sides,undefined,{stage:s=>({type:'stage',x:0,y:0,heading:720,trailCount:sides,closed:true,segmentLengths:Array(sides).fill(Number(s)),segmentAngles:Array.from({length:sides},(_,i)=>-i*720/sides)})});});
F('mreza-pravougaonika',9,'Pozornica','Mreža pravougaonih ćelija',k=>{const columns=k+1;return task(`${columns} kolona`,`Učitaj broj redova od 1 do 4, zatim veličinu ćelije od 5 do 12. Nacrtaj mrežu sa ${columns} kolona koristeći ugrađeni blok pravougaonika. Prije svakog prelaska podigni olovku, pa je spusti za oblik. Ispiši broj ćelija.`,seq(S('redovi',read('Broj redova')),S('a',read('Veličina ćelije')),pen(false),FOR('r',N(0),sub(V('redovi'),N(1)),N(1),FOR('c',N(0),N(columns-1),N(1),go(mul(V('c'),V('a')),mul(V('r'),V('a'))),pen(true),B('edu_rectangle',{},{W:V('a'),H:V('a')}),pen(false))),P(mul(V('redovi'),N(columns)))),[line(2,10),line(1,5),line(3,8)],s=>nums(s)[0]*columns,undefined,{stage:s=>({type:'stage',x:(columns-1)*nums(s)[1],y:(nums(s)[0]-1)*nums(s)[1],heading:0,trailCount:nums(s)[0]*columns,shapes:Array.from({length:nums(s)[0]},(_,r)=>Array.from({length:columns},(_,c)=>({kind:'rectangle',x:c*nums(s)[1],y:r*nums(s)[1],w:nums(s)[1],h:nums(s)[1],angle:0}))).flat()})});});
F('plan-putovanja',9,'Simulacije','Plan prevoza i goriva',k=>{const seats=k*5+20,price=2+k/10;return task(`${seats} sjedišta, gorivo ${price} KM/l`,`Učitaj broj putnika, put u kilometrima i potrošnju litara po 100 km iz tri reda. Autobus ima ${seats} sjedišta. Ispiši potrebni broj autobusa, ukupno gorivo svih autobusa i trošak goriva po ${price} KM/l. Zadnja dva rezultata zaokruži na dvije decimale.`,seq(S('putnici',read('Putnici')),S('km',read('Put u km')),S('potrosnja',read('Litara na 100 km')),S('autobusi',ceil(div(V('putnici'),N(seats)))),S('gorivo',div(mul(mul(V('autobusi'),V('km')),V('potrosnja')),N(100))),P(V('autobusi')),P(R2(V('gorivo'))),P(R2(mul(V('gorivo'),N(price))))),[line(seats+1,100,20),line(0,100,20),line(seats,50,12)],s=>{const[p,km,l]=nums(s),buses=Math.ceil(p/seats),fuel=buses*km*l/100;return[buses,r2(fuel),r2(fuel*price)];});});

const GUIDES={
  'kupovina':['Učitaj dvije količine u a i b.','Napravi dva proizvoda: prva količina × prva cijena i druga količina × druga cijena.','Poveži oba proizvoda sabiranjem i ispiši ukupan iznos.'],
  'kusur':['Učitaj predani iznos i broj artikala.','Trošak je broj artikala pomnožen fiksnom cijenom iz ovog scenarija.','Oduzmi trošak od predanog iznosa; nulti kusur također je valjan rezultat.'],
  'pakovanje':['Učitaj nenegativan broj predmeta n.','Broj punih kutija je količnik n / kapacitet zaokružen prema dolje.','Ostatak dobijaš blokom ostatak pri dijeljenju n sa kapacitetom; ispiši ga u drugom redu.'],
  'trajanje':['Učitaj broj minuta rada.','Pomnoži minute sa 60 da dobiješ sekunde rada.','Dodaj navedenu pauzu u sekundama i ispiši ukupno trajanje.'],
  'put':['Učitaj vrijeme u satima, bez pretvaranja u minute.','Pomnoži vrijeme zadanom brzinom da dobiješ novi dio puta.','Dodaj već pređeni dio puta i ispiši zbir u kilometrima.'],
  'obim-poligona':['Učitaj dužinu jedne stranice a.','Pravilni mnogougao ima sve stranice jednake, pa obim čini broj stranica × a.','U ispis priključi proizvod, a ne unaprijed izračunat broj.'],
  'povrsina-pravougaonika':['Učitaj dužinu ploče.','Pomnoži je fiksnom širinom; dužina i širina su u centimetrima.','Ispiši površinu u kvadratnim centimetrima, bez dopisivanja jedinice u konzolu.'],
  'povrsina-trougla':['Učitaj visinu h koja odgovara navedenoj osnovici.','Sastavi proizvod osnovica × h i podijeli ga sa 2.','Ispiši površinu; ne koristi obim umjesto površine.'],
  'pretvaranje-jedinica':['Učitaj broj velikih jedinica.','Broj malih jedinica dobijaš množenjem faktorom navedenim u zadatku.','Ispiši proizvod; ovo je model datog odnosa jedinica, bez mijenjanja faktora.'],
  'razmjena-bodova':['Učitaj ukupan broj bodova.','Podijeli bodove brojem bodova za jedan žeton.','Količnik zaokruži prema dolje jer se ne izdaje dio žetona.'],
  'pozdrav':['Učitaj ime tekstualnim ulazom, ne numeričkim.','Spoji zadani početak poruke, uneseno ime i uzvičnik.','Pazi na zarez i razmak ispred imena: automatska provjera poredi cijelu poruku.'],
  'duzina-oznake':['Učitaj oznaku kao tekst kako početne nule ne bi nestale.','Dodaj navedeni prefiks ispred oznake i sačuvaj puni kod.','Ispiši kod, pa dužinu upravo tog sastavljenog teksta.'],
  'ponavljanje-poruke':['Učitaj broj ponavljanja n.','U tijelo petlje ponovi n puta stavi jedan blok za ispis zadane poruke.','Ne ispisuj brojač: traže se ponovljene poruke u odvojenim redovima.'],
  'korak-niza':['Učitaj broj članova n i postavi vrijednost na zadani početak.','U svakom ponavljanju prvo ispiši trenutnu vrijednost.','Zatim uvećaj vrijednost zadanim korakom; petlju ponovi tačno n puta.'],
  'odbrojavanje':['Učitaj broj intervala n i početno vrijeme postavi na n × dužina intervala.','Ispiši vrijeme pa ga smanji za jedan interval, ukupno n puta.','Poslije petlje ispiši Kreni!; nula se u ovom zadatku ne ispisuje.'],
  'tablica-mnozenja':['Učitaj broj redova n.','Koristi petlju sa brojačem i od 1 do n, korakom 1.','U tijelu ispiši zadani množilac × i, bez dodatnih oznaka tablice.'],
  'zbir-serije':['Zbir prije petlje postavi na 0 i učitaj broj rundi n.','Brojač i prolazi kroz runde od 1 do n; zbir povećavaj za i × vrijednost boda.','Ispiši zbir tek nakon petlje, da ne dobiješ više međurezultata.'],
  'ponderisani-prosjek':['Učitaj oba rezultata.','Prvi rezultat pomnoži njegovom težinom, dodaj drugi rezultat i podijeli zbirom težina.','Za dvije decimale zaokruži prosjek × 100, zatim podijeli sa 100.'],
  'crtanje-poligona':['Učitaj stranicu a. Broj ponavljanja jednak je broju stranica iz zadatka.','Tijelo petlje je kretanje za a pa okretanje za 360 / broj_stranica.','Lik treba završiti na početku; ispiši obim a × broj_stranica.'],
  'stepenice':['Učitaj broj stepenica n.','Jedna stepenica: idi širinu, okreni −90°, idi visinu, okreni +90°.','Ponovi n puta. Završni smjer je desno, a broj nacrtanih duži 2n.'],
  'djeljivost':['Učitaj cijeli broj n.','Uslov je n mod zadani_djelilac = 0; i broj 0 je djeljiv svakim navedenim nenultim djeliocem.','Granom ako ispiši DA, a granom inače NE.'],
  'dvostruka-djeljivost':['Učitaj n i napravi dvije provjere ostatka dijeljenja.','Obje provjere poveži logičkim I, jer broj mora zadovoljiti oba uslova.','Ispiši DA samo u istinitoj grani, inače NE.'],
  'zaokruzivanje-pakovanja':['Učitaj broj predmeta n.','Podijeli n kapacitetom kutije.','Količnik zaokruži prema gore: i jedan preostali predmet zahtijeva dodatnu kutiju; n=0 daje 0.'],
  'temperaturni-prag':['Učitaj temperaturu kao broj.','Poredi je sa zadanim pragom koristeći strogo veće, a ne veće ili jednako.','Na samom pragu rezultat je normalna; iznad praga visoka.'],
  'dozvoljeni-raspon':['Učitaj n.','Provjeri n ≥ donja granica i n ≤ gornja granica, povezano logičkim I.','Obje granične vrijednosti pripadaju intervalu; izvan njega ispisuje se izvan.'],
  'minimum-mjerenja':['Učitaj tri mjerenja i početni minimum postavi na prvo.','Ako je drugo manje od minimuma, zamijeni minimum; zatim isto provjeri za treće.','Od pronađenog minimuma oduzmi zadanu korekciju i ispiši rezultat.'],
  'maksimum-mjerenja':['Učitaj tri mjerenja i početni maksimum postavi na prvo.','Uporedi drugo pa treće s trenutnim maksimumom, zamjenjujući ga kad pronađeš veće.','Pronađenom maksimumu dodaj zadanu korekciju i ispiši ga.'],
  'odstupanje':['Učitaj mjerenje x.','Oduzmi cilj od x da dobiješ potpisanu razliku.','Priključi razliku na blok apsolutna vrijednost; ispiši nenegativan rezultat.'],
  'dodatak-procenat':['Učitaj osnovnu cijenu.','Konačna cijena je osnovna cijena × (100 + procenat) / 100.','Zaokruži na dvije decimale množenjem sa 100, zaokruživanjem i ponovnim dijeljenjem.'],
  'popust':['Učitaj cijenu prije popusta.','Nakon popusta ostaje 100 − procenat posto početne cijene.','Pomnoži tim odnosom i zaokruži rezultat na dvije decimale.'],
  'tarifa':['Učitaj potrošnju i račun postavi na osnovnu pretplatu.','Samo kada potrošnja prelazi uključene jedinice, dodaj (potrošnja − uključeno) × cijena dodatne jedinice.','Za manju ili jednaku potrošnju račun ostaje osnovna pretplata.'],
  'razlomak-zbir':['Učitaj brojilac c i imenilac d drugog razlomka; prvi je p/q iz zadatka.','Novi brojilac je p×d + c×q, a novi imenilac q×d.','Ispiši brojilac i imenilac odvojeno. U ovoj početnoj vježbi rezultat se ne skraćuje.'],
  'razlomak-razlika':['Učitaj drugi razlomak c/d; prvi je p/q.','Novi brojilac je p×d − c×q, a imenilac q×d.','Razlika može imati negativan brojilac; ne pretvaraj ga u apsolutnu vrijednost.'],
  'razlomak-proizvod':['Učitaj brojilac i imenilac drugog razlomka.','Množi brojioce međusobno p×c, a imenioce međusobno q×d.','Ispiši novi brojilac, zatim novi imenilac; nema unakrsnog sabiranja.'],
  'razlomak-kolicnik':['Učitaj drugi razlomak c/d sa nenultim brojiocem.','Dijeljenje p/q sa c/d pretvori u množenje p/q sa d/c.','Novi brojilac je p×d, imenilac q×c; ispiši oba bez skraćivanja.'],
  'zbir-visekratnika':['Zbir postavi na 0 i učitaj gornju granicu n.','Prođi kroz i od 1 do n; dodaj i samo kada je ostatak pri dijeljenju zadanim brojem 0.','Ispiši konačni zbir. Ako nijedan broj ne odgovara, zbir ostaje 0.'],
  'uzastopni-proizvod':['Učitaj broj činilaca n; proizvod počinje od 1.','Brojač prolazi od zadanog početka do početak + n − 1.','U svakom prolazu pomnoži dosadašnji proizvod brojačem; ispiši ga poslije petlje.'],
  'stepen-ponavljanjem':['Učitaj eksponent n i rezultat postavi na 1.','Ponovi n puta: rezultat postaje rezultat × zadana osnova.','Za n=0 petlja se preskače i ispis ostaje 1.'],
  'zbir-ulazne-liste':['Napravi praznu listu i učitaj zadani broj mjerenja, dodajući svaki broj na kraj liste.','Zbir postavi na 0; prođi kroz pozicije od 1 do dužine liste i dodaj svaki element.','Ispiši zbir nakon završetka prolaza, uključujući negativne vrijednosti.'],
  'brojac-praga':['Prvo učitaj n i zatim n mjerenja u listu.','Brojač postavi na 0; povećaj ga samo za elemente strogo veće od zadanog praga.','Element jednak pragu se ne broji. Ispiši završni brojač.'],
  'nzd':['Postavi a na uneseni broj, a b na zadani ciklus.','Dok b nije 0, sačuvaj a mod b pa postavi a na staro b, a b na sačuvani ostatak.','Kada petlja završi, a je najveći zajednički djelilac.'],
  'nzs':['Učitaj prvi period i postavi drugi period prema zadatku. Sačuvaj njihov proizvod prije mijenjanja varijabli.','Euklidovom petljom nađi NZD početnih perioda.','NZS je sačuvani proizvod podijeljen NZD-om.'],
  'prvi-prost':['Rezultat na početku postavi na 0. Kandidati idu od unesenog početka do zadane granice.','Za još nepronađen rezultat, kandidata smatraj prostim dok ne nađeš djelilac d sa d² ≤ kandidat.','Sačuvaj samo prvi prost kandidat; ne prepisuj ga kasnijim prostim brojem.'],
  'djelioci-interval':['Učitaj n i postavi brojač na 0.','Isprobaj svakog djelitelja d od zadane donje granice do n.','Brojač povećaj kada je n mod d jednak 0, pa ga ispiši.'],
  'zbir-cifara-osnove':['Učitaj dekadnu vrijednost n i postavi zbir na 0.','Dok n > 0, posljednja cifra u zadanoj osnovi je n mod osnova; dodaj je zbiru.','Ukloni cifru postavljanjem n na zaokružen prema dolje količnik n/osnova. Za 0 zbir je 0.'],
  'obrnute-cifre':['Rezultat na početku postavi na 0.','Dok n > 0, rezultat postaje rezultat × osnova + n mod osnova.','Nakon svakog koraka ukloni posljednju cifru cjelobrojnim dijeljenjem n/osnova.'],
  'iz-osnove':['Učitaj zapis kao tekst i rezultat postavi na 0.','Za svaki znak pronađi njegovu poziciju u 0123456789ABCDEF i oduzmi 1 da dobiješ cifru.','Rezultat ažuriraj formulom rezultat × osnova + cifra.'],
  'u-osnovu':['Učitaj dekadni n. Za n=0 odmah postavi tekst zapisa na 0.','Dok n>0, ostatak n mod osnova pretvori u znak iz 0123456789ABCDEF.','Znak dodaj ispred dosadašnjeg zapisa i n podijeli osnovom uz zaokruživanje prema dolje.'],
  'kvadratni-model':['Učitaj x.','Hornerov raspored izbjegava poseban blok stepena: prvo a×x+b, zatim taj rezultat pomnoži sa x.','Dodaj konstantu c i ispiši vrijednost; negativan x također je valjan.'],
  'aritmeticki-zbir':['Učitaj broj članova, trenutni član postavi na zadani početak, a zbir na 0.','U petlji dodaj trenutni član zbiru.','Nakon dodavanja uvećaj član razlikom niza. Ponovi tačno n puta.'],
  'geometrijski-zbir':['Početni član postavi prema zadatku, a zbir na 0.','Dodaj član zbiru, zatim udvostruči član.','Ponavljaj za uneseni broj članova i ispiši konačni zbir.'],
  'rekurentni-niz':['Postavi a i b na prva dva člana niza iz zadatka.','Ponovi n−1 puta: sljedeći=a+b, a=b, b=sljedeći; privremena varijabla sprečava gubitak stare vrijednosti.','Ispiši a. Za n=1 petlja se ne izvršava.'],
  'rast-do-cilja':['Učitaj početnu vrijednost i brojač postavi na 0.','Dok je vrijednost manja od cilja, udvostruči je i povećaj brojač.','Ispiši broj koraka i završnu vrijednost; kad je unos već na cilju, broj koraka je 0.'],
  'godisnji-rast':['Učitaj iznos i broj godina.','U svakoj godini pomnoži iznos sa (100 + godišnji procenat)/100; rast se računa na već uvećani iznos.','Zaokruži samo završni iznos na dvije decimale.'],
  'translacija':['Učitaj koordinate x i y iz dva reda.','Novu x dobiješ dodavanjem x-komponente vektora, a novu y dodavanjem y-komponente.','Ispiši novu x pa novu y, bez mijenjanja redoslijeda.'],
  'rastojanje-tacke':['Učitaj x i y i oduzmi odgovarajuće koordinate kontrolne tačke.','Kvadriraj obje razlike, saberi kvadrate i uzmi kvadratni korijen.','Zaokruži rastojanje na dvije decimale; ono ne može biti negativno.'],
  'brojanje-slova':['Učitaj tekst i postavi brojač na 0.','Prođi kroz pozicije od 1 do dužine teksta; za svaki znak traži poziciju u zadanoj grupi.','Ako je pozicija veća od 0, povećaj brojač. Velika i mala slova se razlikuju.'],
  'zamjena-znaka':['Rezultat počinje kao prazan tekst.','Za svaki uneseni znak provjeri je li jednak ciljanom malom slovu; ako jeste, zamijeni ga zadanim velikim slovom.','Odabrani znak dodaj na kraj rezultata i ispiši cijeli rezultat poslije petlje.'],
  'format-duzine':['Učitaj tekst i izračunaj njegovu dužinu.','Za dužinu manju ili jednaku granici upotrijebi blok velika slova.','U drugoj grani upotrijebi blok mala slova; ispisuj tekst, ne njegovu dužinu.'],
  'trazenje-teksta':['Učitaj tekst koji se pretražuje.','Blok prva pozicija teksta traži zadani obrazac unutar unosa.','Blockly pozicije počinju od 1; kad obrasca nema, blok vraća 0.'],
  'minimum-liste':['Učitaj sve elemente u listu. Minimum postavi na prvi element, ne na 0.','Prođi od druge do zadnje pozicije i zamijeni minimum kada vidiš manji element.','Ispiši minimum; postupak radi i kada su svi elementi negativni.'],
  'maksimum-liste':['Učitaj sve elemente; maksimum postavi na prvi.','Jednim prolazom upoređuj svaki naredni element s trenutnim maksimumom.','Maksimum mijenjaj samo za veći element i ispiši ga poslije petlje.'],
  'prosjek-liste':['Učitaj sve elemente u listu i inicijalizuj zbir na 0.','Saberi listu prolaskom kroz njene pozicije.','Podijeli zbir stvarnom dužinom liste i zaokruži na dvije decimale.'],
  'djeljivi-u-listi':['Učitaj n i zatim n elemenata u listu.','Za svaki element testiraj ostatak dijeljenja zadanim djeliocem.','Ispiši element samo kad je ostatak 0; čuvaj originalni redoslijed i duplikate.'],
  'linearno-trazenje':['Poziciju na početku postavi na 0.','Prođi kroz cijelu listu; kada se element podudari sa ciljem, sačuvaj indeks samo ako je pozicija još 0.','Tako se pamti prvo pojavljivanje. Nepronađen cilj ostavlja rezultat 0.'],
  'binarno-trazenje':['Lijevu granicu postavi na 1, desnu na dužinu uređene liste i rezultat na 0.','Dok interval nije prazan i cilj nije pronađen, zaokruži sredinu prema dolje i poredi element s ciljem.','Pomjeri jednu granicu za jedno mjesto iza sredine; kad se podudari, sačuvaj srednju poziciju.'],
  'bubble-sort':['Učitaj elemente u listu. Ponovi n−1 prolaza kroz susjedne parove.','Ako je lijevi element veći od desnog, sačuvaj lijevi u privremenu varijablu i zamijeni par.','Po završetku svih prolaza ispiši listu po redoslijedu od prve do zadnje pozicije.'],
  'selection-sort':['Za trenutnu poziciju i pretpostavi da je minimum na i.','U ostatku liste nađi indeks najmanjeg elementa.','Zamijeni elemente na i i na tom indeksu koristeći privremenu varijablu; nastavi za sljedeći i.'],
  'prefiksni-zbirovi':['Učitaj listu i postavi zbir na 0.','Za svaki element povećaj zbir njegovom vrijednošću.','Odmah ispiši trenutni zbir, pa nastavi; zadnji red je zbir cijele liste.'],
  'pokretni-prosjek':['Učitaj listu; početne pozicije prozora su od 1 do n−širina+1.','Za svaki prozor resetuj zbir na 0 i saberi njegove uzastopne elemente.','Podijeli širinom prozora, zaokruži na dvije decimale i ispiši prije sljedećeg prozora.'],
  'frekvencija-cilja':['Učitaj broj elemenata i listu. Brojač pojavljivanja počinje od 0.','Brojač povećaj za svaki element jednak zadanom cilju.','Ispiši broj pojavljivanja, zatim 100 × brojač / n zaokružen na dvije decimale.'],
  'jedinstvene-vrijednosti':['Napravi praznu drugu listu jedinstvenih vrijednosti.','Prođi kroz ulaznu listu; dodaj element samo kada njegova prva pozicija u drugoj listi iznosi 0.','Ispiši drugu listu bez sortiranja, da ostane redoslijed prvog pojavljivanja.'],
  'medijan-liste':['Učitaj neparan broj elemenata i sortiraj listu uzlazno.','Središnja pozicija je (dužina + 1)/2.','Ispiši element na toj poziciji, a ne aritmetički prosjek svih elemenata.'],
  'filter-intervala':['Učitaj listu. Za svaki element provjeri obje granice.','Uslovi element ≥ donja i element ≤ gornja povezuju se logičkim I.','Ispiši samo odgovarajuće elemente; granične vrijednosti se uključuju.'],
  'transformacija-liste':['Učitaj n i n elemenata.','Za svaki x sastavi izraz koeficijent × x − pomak iz zadatka.','Ispiši transformisane vrijednosti istim redoslijedom kao ulaz.'],
  'skalarni-proizvod':['Učitaj prvi i drugi vektor u dvije liste iste deklarisane dimenzije.','Za svaku koordinatnu poziciju pomnoži odgovarajuća dva elementa i dodaj proizvod zbiru.','Ispiši zbir nakon svih koordinata; nemoj množiti zbirove vektora međusobno.'],
  'trag-matrice':['Učitaj matricu red po red u linearnu listu.','Dijagonalna pozicija za red i je (i−1)×broj_kolona+i.','Saberi elemente na tim pozicijama; elementi izvan dijagonale ne utiču na trag.'],
  'zbirovi-redova':['Učitaj matricu red po red. Vanjska petlja bira red r.','Na početku svakog reda zbir resetuj na 0, pa u unutrašnjoj petlji saberi tri kolone.','Ispiši zbir prije prelaska na novi red; linearni indeks je (r−1)×3+c.'],
  'filter-dva-uzorka':['Učitaj n i listu; susjedni parovi počinju na pozicijama 1 do n−1.','Za svaki par pomnoži prvi uzorak prvom težinom, drugi drugom težinom i saberi.','Ispiši rezultat svakog para; izlaz ima jedan red manje od liste.'],
  'horner-koeficijenti':['Učitaj x; vrijednost polinoma na početku je 0.','Učitaj koeficijente od najvišeg stepena prema konstantnom.','Za svaki koeficijent postavi vrijednost na vrijednost × x + koeficijent; ispiši nakon svih koeficijenata.'],
  'funkcija-afina':['Definiši funkciju model(argument) koja vraća navedeni afini izraz.','U glavnom programu učitaj x.','Ispiši dva poziva iste funkcije: jedan za x, drugi za x+1.'],
  'funkcija-norma':['Definiši funkciju sa dva parametra koja računa koeficijent × prvi² + drugi².','Učitaj a i b u glavnom programu.','Pozovi funkciju prvo sa (a,b), pa sa (b,a). Za različite težine zamjena može promijeniti rezultat; za jednake ostaje isti.'],
  'funkcija-nzd':['Definiši funkciju nzd(a,b) sa Euklidovom petljom i povratnom vrijednošću a.','Učitaj n i ne mijenjaj ga u glavnom programu.','Dvaput pozovi istu funkciju, svaki put s drugim zadanim referentnim brojem.'],
  'postupak-pravougaonika':['Definiši postupak pravougaonik(w,h) bez povratne vrijednosti. Dvaput ponovi idi w, okreni 90°, idi h, okreni 90°.','Glavni program učitava širinu i visinu; s podignutom olovkom pređe na zadanu negativnu x-koordinatu da niz kopija stane na pozornicu.','Poslije svake kopije, uključujući posljednju, podigni olovku i idi 30 koraka; za naredni crtež je ponovo spusti.'],
  'poruka-racunanje':['Prijem poruke izdvoji u zaseban blok i u njega stavi računanje i ispis izraza.','Glavni niz učitava a i šalje poruku tačno istog naziva.','Uvećaj a za 1 pa pošalji poruku ponovo; isti prijem koristi novu vrijednost varijable.'],
  'poruka-crtanje':['U prijem poruke stavi petlju sa brojem stranica iz zadatka.','Petlja ide za unesenu stranicu pa okreće lik za 360/broj_stranica; nakon petlje ispiši obim.','Glavni niz treba samo učitati stranicu i poslati odgovarajuću poruku.'],
  'cezar-sifra':['Učitaj tekst i postavi rezultat na prazan tekst. Abeceda je ABCDEFGHIJKLMNOPQRSTUVWXYZ.','Poziciju svakog slova pretvori iz 1–26 u 0–25, dodaj pomak i uzmi ostatak mod 26.','Vrati poziciju u 1–26, pročitaj novo slovo i dodaj ga rezultatu.'],
  'provjera-lozinke':['Učitaj tekst i dvije oznake prisutnosti postavi na 0.','Prođi kroz znakove; provjeri nalazi li se znak u velikim slovima ili ciframa i postavi odgovarajuću oznaku na 1.','Valjanost zahtijeva sva tri uslova: dovoljnu dužinu, veliko slovo i cifru.'],
  'rle-paketi':['Sačuvaj prvi znak teksta kao trenutni i brojač postavi na 1.','Za svaki sljedeći znak povećaj brojač samo ako je isti i paket još nije dostigao kapacitet.','Inače ispiši prethodni paket znak:broj pa pokreni novi. Posljednji paket ispiši poslije petlje.'],
  'izvod-polinoma':['Učitaj x. Za koeficijent stepena d u izvodu se pojavljuje koeficijent × d.','Hornerov postupak provodi za d od najvećeg stepena do 1: rezultat ← rezultat × x + koeficijent × d.','Učitaj i konstantni član da potrošiš ulaz, ali ga ne uključuj jer mu je izvod 0.'],
  'newton-korijen':['Učitaj pozitivan n i početnu aproksimaciju x postavi na n.','Tačno zadani broj puta postavi x na (x + n/x)/2. Ne prekidaj na osnovu slučajne jednakosti decimalnih brojeva.','Zaokruži završnu aproksimaciju na četiri decimale.'],
  'bisekcija-korijen':['Za n≥1 početni interval [0,n] sadrži √n.','Sredina je (lijevo+desno)/2. Ako je njen kvadrat manji od n, pomjeri lijevu granicu; inače desnu.','Poslije zadanog broja koraka ispiši sredinu intervala zaokruženu na četiri decimale.'],
  'trapezna-integracija':['Učitaj b i širinu trapeza h postavi na b/broj_trapeza.','Zbir počinje od b²/2; dodaj kvadrate unutrašnjih tačaka (i×h)² za i od 1 do broj_trapeza−1.','Cijeli zbir pomnoži sa h i zaokruži na četiri decimale. To je trapezna aproksimacija, ne tačna integralna vrijednost.'],
  'budzet-prihod':['Učitaj prihod i tri troška; troškove saberi petljom.','Raspoloživi prihod je prihod × (100−procenat_štednje)/100; od njega oduzmi zbir troškova.','Ispiši ostatak na dvije decimale, pa provjeri je li ≥0 za oznaku pozitivan ili minus.'],
  'kvadratna-jednacina':['Učitaj b i c; a je zadat scenarijem. Diskriminanta je b²−4ac.','Za dozvoljeni ulaz D>0 računaj dva korijena (−b+√D)/(2a) i (−b−√D)/(2a).','Ispiši ih tim redoslijedom, svaki na četiri decimale.'],
  'linearni-sistem':['Učitaj desne strane p i q. Sabiranjem jednačina eliminiše se y.','Dobija se x=(p+q)/(zadani_koeficijent+1), a zatim y=x−q.','Ispiši x pa y, zaokruženo na četiri decimale; provjeri zamjenom u obje jednačine.'],
  'zvucni-niz':['Učitaj početnu frekvenciju i broj tonova.','U svakom ponavljanju odsviraj trenutnu frekvenciju 0,05 sekundi i ispiši je.','Zatim povećaj frekvenciju zadanim korakom; ne mijenjaj trajanje između tonova.'],
  'zvjezdasti-poligon':['Učitaj dužinu duži. Petlju ponovi zadani neparan broj vrhova.','Nakon svake duži okreni lik za 720/broj_vrhova, čime se preskače jedan vrh.','Zatvorena putanja završava na početku; ispiši broj_vrhova × dužina_duži.'],
  'mreza-pravougaonika':['Učitaj broj redova i veličinu ćelije. Vanjska petlja bira red, unutrašnja kolonu.','Sa podignutom olovkom idi na x=kolona×veličina, y=red×veličina; indeksi počinju od 0.','Spusti olovku za blok pravougaonika, nacrtaj kvadratnu ćeliju, pa je podigni prije sljedećeg prelaska.'],
  'plan-putovanja':['Učitaj putnike, dužinu puta i potrošnju. Broj autobusa je količnik putnici/sjedišta zaokružen prema gore.','Ukupno gorivo je broj_autobusa × kilometri × potrošnja/100.','Trošak je gorivo × zadana cijena po litru; ispiši autobuse, gorivo i trošak, s traženim zaokruživanjem.']
};
function checkFor(item,input){const checks=[];if(item.stage)checks.push(item.stage(input));if(item.actions)checks.push(item.actions(input));const expected=out(item.calculate(input));return {type:'output',expected,trim:true,inputCount:input.split('\n').length,...(checks.length?{all:checks}: {})};}
function build(){if(families.length!==100)throw Error('Expected 100 families, got '+families.length);const projects=[];for(const family of families)for(let k=1;k<=10;k++){const item=family.make(k);const solution=project(item.roots);const starter=project(S('ulaz',readText('Unesi podatke prema zadatku')));const tests=item.samples.map(input=>({input:String(input),check:checkFor(item,String(input))}));const steps=GUIDES[family.id];if(!steps)throw Error('Missing algorithm guide: '+family.id);const record={id:`bp-${family.grade}-${family.id}-${String(k).padStart(2,'0')}`,title:family.title+' — '+item.setting,grade:family.grade,category:family.category,difficulty:family.grade-4,familyId:family.id,variant:k,goal:family.title,statement:item.statement,description:item.statement,input:tests[0].input,expected:tests[0].check.expected,check:tests[0].check,hints:steps,steps,starter,solution,tests,source:{kind:'original',collection:'ELDI EDU',family:family.id,scenario:item.setting}};projects.push(record);}const cleanFamilies=families.map(({make,...f})=>f);const catalog={format:'ELDI-BLOCK-PROJECTS',version:1,title:'1000 riješenih blokovskih projekata',description:'100 algoritamskih porodica, svaka sa 10 različitih postavki. Svi projekti čitaju podatke sa ulaza; tri provjerna primjera prate svaki projekat.',families:cleanFamilies,projects};const validator=require('../app/block-project-catalog.js');validator.validateCatalog(catalog);const target=path.join(root,'content/block-projects.json');fs.writeFileSync(target,JSON.stringify(catalog)+'\n');return {projects:projects.length,families:families.length,cases:projects.reduce((sum,p)=>sum+p.tests.length,0),bytes:fs.statSync(target).size};}
if(require.main===module)console.log(JSON.stringify(build()));
module.exports={build,families,project};
